        local VirtualInputManager = nil
        pcall(function() VirtualInputManager = game:GetService("VirtualInputManager") end)

        -- Auto Parry V1 settings are kept in the existing VD config table.
        local APV1Config = getgenv().VD or {}
        APV1Config.AutoParryV1 = APV1Config.AutoParryV1 == true
        APV1Config.AutoParryV1Safety = APV1Config.AutoParryV1Safety == true
