        APV1Config.AutoParryV1Circle = APV1Config.AutoParryV1Circle ~= false
        APV1Config.AutoParryV1Radius = tonumber(APV1Config.AutoParryV1Radius) or 15
        APV1Config.AutoParryV1Face = tonumber(APV1Config.AutoParryV1Face) or 0.7
        APV1Config.AutoParryV1FaceEnabled = APV1Config.AutoParryV1FaceEnabled ~= false
        APV1Config.AutoParryV1IgnoredSkills = type(APV1Config.AutoParryV1IgnoredSkills) == "table" and APV1Config.AutoParryV1IgnoredSkills or {}

        -- Auto Parry V3 now uses a dedicated  engine with settings independent from V1/V2.
        local APV3 = { Config = getgenv().VD or {} }
        APV3.Config.AutoParryV3 = APV3.Config.AutoParryV3 == true
        APV3.Config.AutoParryV3Safety = APV3.Config.AutoParryV3Safety ~= false
        APV3.Config.AutoParryV3Radius = math.clamp(tonumber(APV3.Config.AutoParryV3Radius) or 15, 5, 25)
        APV3.Config.AutoParryV3Face = math.clamp(tonumber(APV3.Config.AutoParryV3Face) or 0.85, -1, 1)
        APV3.Config.AutoParryV3Circle = APV3.Config.AutoParryV3Circle ~= false
        APV3.Config.AutoParryV3IgnoredSkills = type(APV3.Config.AutoParryV3IgnoredSkills) == "table" and APV3.Config.AutoParryV3IgnoredSkills or {}
        APV3.Config.AutoParryV3IgnoreHiddenS1 = APV3.Config.AutoParryV3IgnoreHiddenS1 == true or APV3.Config.AutoParryV3IgnoredSkills["Hidden S1"] == true
        APV3.Config.AutoParryV3IgnoreAbyssalS1 = APV3.Config.AutoParryV3IgnoreAbyssalS1 == true or APV3.Config.AutoParryV3IgnoredSkills["Abyssal S1"] == true
        if APV3.Config.AutoParryV3IgnoreHiddenS1 then APV3.Config.AutoParryV3IgnoredSkills["Hidden S1"] = true end
        if APV3.Config.AutoParryV3IgnoreAbyssalS1 then APV3.Config.AutoParryV3IgnoredSkills["Abyssal S1"] = true end
        APV3.Config.AutoParryV3Aggressive = APV3.Config.AutoParryV3Aggressive == true
        APV3.Config.AutoParryV3GuiVisible = APV3.Config.AutoParryV3GuiVisible == true

        local UILib = __MAWWW_UI_ADAPTER
