            V2_UpdateRangeCircle = function()
                local parryV2 = _G.Ox.ParryV2
                local rangeAdornment = parryV2.RangeAdornment
                if not rangeAdornment then
                    return
                end

                if parryV2.Enabled and parryV2.ShowCircle then
