                Instance.new("UICorner", liveDot).CornerRadius = UDim.new(1, 0)
                local liveText = Instance.new("TextLabel")
                liveText.Name = "LiveText"
                liveText.BackgroundTransparency = 1
                liveText.Position = UDim2.fromOffset(13, 0)
                liveText.Size = UDim2.new(1, -14, 1, 0)
                liveText.Font = Enum.Font.GothamBold
                liveText.Text = "LIVE"
                liveText.TextSize = 8
                liveText.TextColor3 = Color3.fromRGB(240, 240, 250)
                liveText.ZIndex = 105
                liveText.Parent = livePill

                local minimize = Instance.new("TextButton")
                minimize.Name = "MinimizePanel"
                minimize.AnchorPoint = Vector2.new(1, 0)
                minimize.Position = UDim2.new(1, -7, 0, 6)
                minimize.Size = UDim2.fromOffset(22, 22)
                minimize.BackgroundColor3 = Color3.fromRGB(29, 28, 43)
                minimize.BorderSizePixel = 0
