                minStroke.Parent = minimize

                local separator = Instance.new("Frame")
                separator.Name = "HeaderSeparator"
                separator.Position = UDim2.new(0, 10, 0, 39)
                separator.Size = UDim2.new(1, -20, 0, 1)
                separator.BackgroundColor3 = Color3.fromRGB(164, 136, 255)
                separator.BackgroundTransparency = 0.45
                separator.BorderSizePixel = 0
                separator.ZIndex = 103
                separator.Parent = panel

                local statusLines = {}
                local minimized = false
                minimize.Activated:Connect(function()
                    minimized = not minimized
                    for _, statusLine in ipairs(statusLines) do
                        if statusLine and statusLine.Parent then statusLine.Visible = not minimized end
                    end
                    for _, child in ipairs(panel:GetChildren()) do
                        if child:IsA("GuiButton") and child.Name:find("Toggle") then
                            child.Visible = not minimized
                        end
                    end
                    panel.Size = UDim2.fromOffset(panelWidth, minimized and 42 or panelHeight)
                    minimize.Text = minimized and "+" or "—"
                    AP_UpdateGuiVisibility()
                end)
                AP_MakeDraggablePanel(panel, title)

                local function makeStatusLine(lineName, lineText, y, color)
                    local line = Instance.new("TextLabel")
                    line.Name = lineName
                    line.BackgroundColor3 = Color3.fromRGB(19, 19, 31)
                    line.BackgroundTransparency = 0.08
                    line.BorderSizePixel = 0
                    line.Position = UDim2.fromOffset(8, y)
                    line.Size = UDim2.new(1, -92, 0, 31)
                    line.Font = Enum.Font.GothamBold
                    line.Text = lineText
                    line.TextSize = 9
                    line.TextColor3 = color
                    line.TextXAlignment = Enum.TextXAlignment.Left
                    line.TextTruncate = Enum.TextTruncate.AtEnd
                    line.ZIndex = 103
                    line.Parent = panel
                    Instance.new("UICorner", line).CornerRadius = UDim.new(0, 8)
                    local padding = Instance.new("UIPadding")
                    padding.PaddingLeft = UDim.new(0, 10)
                    padding.PaddingRight = UDim.new(0, 5)
                    padding.Parent = line
