        function W.SInd_SetEnabled(v)
            SInd.Enabled = v and true or false
            if SInd.Enabled then
                if SInd.HeartbeatConn then return end
                SInd.HeartbeatConn = RunService.Heartbeat:Connect(function()
                    if not SInd.Enabled then return end
                    local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if not myRoot then return end
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and TeamIs(p, "Killer") and p.Character then
                            local char = p.Character
                            local hrp = char:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                local dist = (hrp.Position - myRoot.Position).Magnitude
                                local stunned = SInd_IsStunned(char)
                                local data = SInd.Cache[char]
                                local wasStunned = data ~= nil
                                if stunned and dist <= SInd.Range then
                                    if not wasStunned then SInd_PlaySound(char); SInd_Create(char) end
                                else
                                    if wasStunned then
                                        if data.Exit then data.Exit() else SInd_Remove(char) end
                                        SInd.Cache[char] = nil
                                    end
                                end
                            end
                        end
                    end
                end)
            else
                if SInd.HeartbeatConn then SInd.HeartbeatConn:Disconnect(); SInd.HeartbeatConn = nil end
                for _, data in pairs(SInd.Cache) do
                    pcall(function()
                        if data.StopAnim then data.StopAnim() end
                        if data.Gui then data.Gui:Destroy() end
                    end)
                end
                SInd.Cache = {}
            end
        end

        W.TrollTeleport = W.TrollTeleport or {
            Enabled = false, IsProcessing = false, TriggerCount = 0,
            AnimatorHook = nil, CharHook = nil,
            BlockedAnimList = { ["123812278891591"] = 1, ["74099023522626"] = 2 },
        }
        local TT = W.TrollTeleport
        local function TT_HookCharacter(char)
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            local anim = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 3)
            if not anim then return end
            local root = char:FindFirstChild("HumanoidRootPart")
            if not root then return end
            anim.AnimationPlayed:Connect(function(track)
                if not TT.Enabled then return end
                if TT.IsProcessing then return end
                local aid = track.Animation and track.Animation.AnimationId or ""
                local numId = aid:match("%d+")
                local delay = numId and TT.BlockedAnimList[numId]
                if not delay then return end
                TT.IsProcessing = true
                TT.TriggerCount = TT.TriggerCount + 1
                local startCF = root.CFrame
                VD_Notify("Troll Teleport", "Trigger #" .. TT.TriggerCount .. " | Delay " .. delay .. "s", 2)
                task.spawn(function()
                    if track.IsPlaying then pcall(function() track.Stopped:Wait() end) end
                    task.wait(delay)
                    local c = LocalPlayer.Character
                    local rp = c and c:FindFirstChild("HumanoidRootPart")
                    if rp and rp.Parent then pcall(function() rp.CFrame = startCF end) end
                    TT.IsProcessing = false
                end)
            end)
        end
        function W.TrollTeleport_Start()
            if TT.AnimatorHook then return end
            TT.IsProcessing = false
            TT_HookCharacter(LocalPlayer.Character)
            TT.CharHook = LocalPlayer.CharacterAdded:Connect(function(c) task.wait(0.4); TT_HookCharacter(c) end)
        end
        function W.TrollTeleport_Stop()
            if TT.CharHook then pcall(function() TT.CharHook:Disconnect() end); TT.CharHook = nil end
            TT.AnimatorHook = nil
            TT.IsProcessing = false
        end
        function W.TrollTeleport_SetEnabled(v)
            TT.Enabled = v and true or false
            if TT.Enabled then W.TrollTeleport_Start() else W.TrollTeleport_Stop() end
        end

        W.Escape = W.Escape or { Enabled = false, FinishLineName = "fininshline", TeleportCount = 0 }
        local Esc = W.Escape
        function W.Escape_Teleport()
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not root then ForceNotify("Escape", "Character not found", 2); return false end
            local found = nil
            for _, obj in ipairs(Workspace:GetDescendants()) do
                if string.lower(obj.Name) == string.lower(Esc.FinishLineName) and obj:IsA("BasePart") then
                    found = obj; break
                end
            end
            if not found then ForceNotify("Escape", "Finish line not found", 2); return false end
            pcall(function() root.CFrame = found.CFrame + Vector3.new(0, 5, 0) end)
            Esc.TeleportCount = Esc.TeleportCount + 1
            VD_Notify("Instant Escape", "Teleported! (#" .. Esc.TeleportCount .. ")", 2)
            return true
        end

        do
            -- Replaced legacy Auto Farm backend with the finish-line logic from the provided farm source.
            local AF = W.N3K0_AutoFarm or {}
            W.N3K0_AutoFarm = AF
            AF.Status = "Idle"
            AF.StartTime = 0
            AF.Thread = nil
            AF.Running = false
            AF.BeatSurvivorDone = false
            AF.LastFinishPos = nil
            -- Safety: Auto Farm and Server Hop must never resume just because the script was re-executed.
            VD.AF_Enabled = false
            AF.ServerHop = false
            AF.Hopping = false
            AF.LastRole = nil
            AF.CompletedRuns = tonumber(AF.CompletedRuns) or 0
            -- The webhook URL is intentionally runtime-only and is never written to config files.
            AF.WebhookURL = ""
            AF.WebhookEnabled = AF.WebhookEnabled == true
            AF.WebhookLastSentAt = AF.WebhookLastSentAt or 0
            AF.WebhookLastEvent = AF.WebhookLastEvent or {}
            local AF_TeleportService = game:GetService("TeleportService")

            local function AF_IsValidWebhookURL(url)
                if type(url) ~= "string" then return false end
                -- Accept only the official Discord webhook endpoint; reject query strings and fragments.
                return url:match("^https://discord%.com/api/webhooks/%d+/[%w_-]+$") ~= nil
            end

            local function AF_GetRequestFunction()
                local req
                pcall(function() if type(request) == "function" then req = request end end)
                if req then return req end
                pcall(function() if type(http_request) == "function" then req = http_request end end)
                if req then return req end
                pcall(function()
                    if type(syn) == "table" and type(syn.request) == "function" then req = syn.request end
                end)
                if req then return req end
                pcall(function()
                    if type(http) == "table" and type(http.request) == "function" then req = http.request end
                end)
                if req then return req end
                pcall(function()
                    local env = type(getgenv) == "function" and getgenv() or nil
                    if type(env) == "table" then
                        if type(env.request) == "function" then req = env.request
                        elseif type(env.http_request) == "function" then req = env.http_request end
                    end
                end)
                return req
            end

            function AF.SendWebhook(eventTitle, details, forceSend, showResult)
                if not forceSend and not AF.WebhookEnabled then return false, "notifications disabled" end
                local url = tostring(AF.WebhookURL or "")
                if not AF_IsValidWebhookURL(url) then
                    if showResult then ForceNotify("Discord Webhook", "URL belum diisi atau format URL tidak valid.", 3) end
                    return false, "invalid webhook URL"
                end

                local nowClock = os.clock()
                if nowClock - (AF.WebhookLastSentAt or 0) < 1.5 then
                    if showResult then ForceNotify("Discord Webhook", "Tunggu sebentar sebelum mengirim lagi.", 2) end
                    return false, "rate limited locally"
                end
                AF.WebhookLastSentAt = nowClock

                local safeTitle = tostring(eventTitle or "Auto Farm Update"):sub(1, 256)
                local safeDetails = tostring(details or ""):sub(1, 1000)
                local roleText = "Unknown"
                pcall(function() roleText = tostring(GetRole() or "Unknown") end)
                local runtimeSeconds = 0
                if AF.StartTime and AF.StartTime > 0 and AF.Running then
                    runtimeSeconds = math.max(0, math.floor(tick() - AF.StartTime))
                end
                local minutes = math.floor(runtimeSeconds / 60)
                local seconds = runtimeSeconds % 60
                local color = 0x48A6FF
                if string.find(string.lower(safeTitle), "finish", 1, true) then color = 0x52E79A end
                if string.find(string.lower(safeTitle), "error", 1, true) or string.find(string.lower(safeTitle), "failed", 1, true) then color = 0xFF4C5C end
                if string.find(string.lower(safeTitle), "stop", 1, true) then color = 0xA0A7B4 end

                local payload = {
                    username = "Mawww Hub • Auto Farm",
                    allowed_mentions = { parse = {} },
                    embeds = {{
                        title = safeTitle,
                        description = safeDetails,
                        color = color,
                        fields = {
                            { name = "Status", value = tostring(AF.Status or "Idle"):sub(1, 1000), inline = true },
                            { name = "Role", value = roleText:sub(1, 100), inline = true },
                            { name = "Runtime", value = string.format("%dm %02ds", minutes, seconds), inline = true },
                            { name = "Place ID", value = tostring(game.PlaceId), inline = true },
                            { name = "Finish Count", value = tostring(AF.CompletedRuns or 0), inline = true },
                        },
                        timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
                    }},
                }

                local encodedOK, body = pcall(function() return HttpService:JSONEncode(payload) end)
                if not encodedOK or type(body) ~= "string" then
                    if showResult then ForceNotify("Discord Webhook", "Gagal menyiapkan payload JSON.", 3) end
                    return false, "JSON encode failed"
                end

                task.spawn(function()
                    local req = AF_GetRequestFunction()
                    local requestOK, response = pcall(function()
                        local requestData = {
                            Url = url,
                            Method = "POST",
                            Headers = { ["Content-Type"] = "application/json" },
                            Body = body,
                        }
                        if req then return req(requestData) end
                        -- Fallback for environments that expose HttpService HTTP requests.
                        return HttpService:RequestAsync(requestData)
                    end)
                    local statusCode = requestOK and type(response) == "table" and tonumber(response.StatusCode or response.Status) or nil
                    local success = requestOK and type(response) == "table" and (
                        response.Success == true or (statusCode ~= nil and statusCode >= 200 and statusCode < 300)
                    )
                    if success then
                        if showResult then ForceNotify("Discord Webhook", "Test berhasil dikirim ke Discord.", 3) end
                    else
                        local reason = requestOK and ("HTTP status " .. tostring(statusCode or "unknown")) or tostring(response)
                        warn("[MAWWW Discord Webhook] Request failed: " .. reason)
                        if showResult then
                            ForceNotify("Discord Webhook", "Gagal mengirim. Pastikan executor mendukung request HTTP dan URL benar.", 4)
                        end
                    end
                end)
                return true, "queued"
            end

            local function AF_FindFinishPosition(map)
                if not map then return nil end
                local function has(name) return map:FindFirstChild(name, true) ~= nil end
                -- These map fallbacks are present in the supplied Auto Farm source.
                if has("RooftopHitbox") or has("Rooftop") then return Vector3.new(3098.16, 454.04, -4918.74) end
                if has("HooksMeat") then return Vector3.new(1546.12, 152.21, -796.72) end
                if has("churchbell") then return Vector3.new(760.98, -20.14, -78.48) end
                for _, wanted in ipairs({"Finishline", "FinishLine", "Fininshline", "finishline", "finish"}) do
                    local found = map:FindFirstChild(wanted, true)
                    if found then
                        if found:IsA("BasePart") then return found.Position end
                        if found:IsA("Model") then
                            local part = found.PrimaryPart or found:FindFirstChildWhichIsA("BasePart", true)
                            if part then return part.Position end
                        end
                    end
                end
                for _, desc in ipairs(map:GetDescendants()) do
                    if string.find(string.lower(desc.Name), "finish", 1, true) then
                        if desc:IsA("BasePart") then return desc.Position end
                        if desc:IsA("Model") then
                            local part = desc.PrimaryPart or desc:FindFirstChildWhichIsA("BasePart", true)
                            if part then return part.Position end
                        end
                    end
                end
                for _, material in ipairs({Enum.Material.Limestone, Enum.Material.Leather}) do
                    for _, desc in ipairs(map:GetDescendants()) do
                        if desc:IsA("MeshPart") and desc.Material == material then
                            if material == Enum.Material.Limestone then return Vector3.new(-947.9, 152.12, -7579.52) end
                            return Vector3.new(1546.12, 152.21, -796.72)
                        end
                    end
                end
                return nil
            end
            AF.FindFinishPosition = AF_FindFinishPosition

            local function AF_HopNow()
                if AF.Hopping then return false end
                AF.Hopping = true
                AF.Status = "Searching server..."
                AF.SendWebhook("Server Hop", "Mencari server publik lain.")
                local ok, data = pcall(function()
                    local url = string.format("https://games.roblox.com/v1/games/%s/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true", tostring(game.PlaceId))
                    return HttpService:JSONDecode(game:HttpGet(url))
                end)
                if ok and type(data) == "table" and type(data.data) == "table" then
                    for _, server in ipairs(data.data) do
                        if type(server) == "table" and server.id and server.id ~= game.JobId
                            and tonumber(server.playing) and tonumber(server.maxPlayers)
                            and server.playing < server.maxPlayers then
                            AF.Status = "Teleporting to server..."
                            local teleOK = pcall(function()
                                AF_TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
                            end)
                            if teleOK then
                                task.delay(12, function()
                                    if AF.Hopping then
                                        AF.Hopping = false
                                        if VD.AF_Enabled then AF.Status = "Server hop timed out" end
                                    end
                                end)
                                return true
                            end
                        end
                    end
                    AF.Status = "No available server found"
                    AF.SendWebhook("Server Hop Failed", "Tidak ditemukan server publik yang tersedia.")
                else
                    AF.Status = "Server list unavailable"
                    AF.SendWebhook("Server Hop Failed", "Daftar server tidak bisa diakses.")
                end
                AF.Hopping = false
                return false
            end
            AF.HopNow = AF_HopNow

            local function AF_ProcessSurvivorFarm()
                local character = LocalPlayer.Character
                local root = character and character:FindFirstChild("HumanoidRootPart")
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                if not root or not humanoid or humanoid.Health <= 0 then AF.Status = "Waiting for character"; return end
                local map = Workspace:FindFirstChild("Map")
                if not map then AF.Status = "Waiting for map"; return end
                local finishPos = AF_FindFinishPosition(map)
                if not finishPos then AF.Status = "Finish not found on this map"; return end
                if AF.LastFinishPos and (finishPos - AF.LastFinishPos).Magnitude > 50 then AF.BeatSurvivorDone = false end
                if AF.BeatSurvivorDone then AF.Status = "Finish reached"; return end
                AF.Status = "Finish found • waiting 6s"
                task.wait(6)
                if not VD.AF_Enabled or not AF.Running or GetRole() ~= "Survivor" then AF.Status = "Cancelled"; return end
                character = LocalPlayer.Character
                root = character and character:FindFirstChild("HumanoidRootPart")
                humanoid = character and character:FindFirstChildOfClass("Humanoid")
                if not root or not humanoid or humanoid.Health <= 0 then AF.Status = "Character missing"; return end
                local moved = pcall(function() root.CFrame = CFrame.new(finishPos + Vector3.new(0, 3, 0)) end)
                if not moved then AF.Status = "Teleport failed"; return end
                AF.BeatSurvivorDone = true
                AF.LastFinishPos = finishPos
                AF.CompletedRuns = (AF.CompletedRuns or 0) + 1
                AF.Status = "Finish reached"
                -- Keep the UI quiet: the ON/OFF toggle is the persistent status indicator.
                AF.SendWebhook("Finish Reached", "Finish line berhasil dicapai oleh Auto Farm.")
                task.delay(5, function()
                    if VD.AF_Enabled and AF.Running and AF.ServerHop and GetRole() == "Survivor" then AF_HopNow() end
                end)
            end

            function AF.Start()
                if AF.Running and AF.Thread then return end
                VD.AF_Enabled = true
                AF.Running = true
                AF.StartTime = tick()
                AF.Status = "Starting..."
                AF.SendWebhook("Auto Farm Started", "Auto Farm diaktifkan.")
                AF.Thread = task.spawn(function()
                    while AF.Running and VD.AF_Enabled do
                        local role = GetRole()
                        if role ~= AF.LastRole then
                            AF.LastRole = role
                            if role == "Survivor" then AF.BeatSurvivorDone = false; AF.LastFinishPos = nil end
                        end
                        if role == "Survivor" then
                            local ok, err = pcall(AF_ProcessSurvivorFarm)
                            if not ok then
                                AF.Status = "Error: " .. tostring(err)
                                warn("[MAWWW Auto Farm]", err)
                                if AF.LastWebhookError ~= AF.Status then
                                    AF.LastWebhookError = AF.Status
                                    AF.SendWebhook("Auto Farm Error", tostring(err):sub(1, 500))
                                end
                            end
                        elseif role == "Killer" then
                            AF.Status = "Waiting for Survivor role"
                        else
                            AF.Status = "Waiting for match"
                        end
                        task.wait(1)
                    end
                    AF.Thread = nil
                    AF.Running = false
                    AF.Status = "Idle"
                end)
            end
            function AF.Stop()
                if AF.Running then AF.SendWebhook("Auto Farm Stopped", "Auto Farm dinonaktifkan.") end
                VD.AF_Enabled = false
                AF.Running = false
                if AF.Thread then pcall(function() task.cancel(AF.Thread) end); AF.Thread = nil end
                AF.Status = "Idle"
            end
            function AF.SetEnabled(value) if value == true then AF.Start() else AF.Stop() end end
            function AF.SetServerHop(value) AF.ServerHop = value == true end
            -- Startup always begins with both automation switches OFF; enable them manually in the UI.
            VD.AF_Enabled = false
            AF.ServerHop = false
            AF.Stop()
        end

        W.Masked = W.Masked or { CurrentPower = "Cobra", Powers = {"Cobra", "Richter", "Brandon", "Rabbit", "Alex", "Tony"} }
        local Masked = W.Masked
        function W.Masked_Activate()
            local ev = ReplicatedStorage:FindFirstChild("Remotes", true)
                and ReplicatedStorage.Remotes:FindFirstChild("Killers", true)
                and ReplicatedStorage.Remotes.Killers:FindFirstChild("Masked", true)
                and ReplicatedStorage.Remotes.Killers.Masked:FindFirstChild("Activatepower")
            if ev then
                pcall(function() ev:FireServer(Masked.CurrentPower) end)
                VD_Notify("Select Masked", "Activated: " .. Masked.CurrentPower, 2)
            else ForceNotify("Select Masked", "Activatepower remote not found", 2) end
        end
        function W.Masked_Deactivate()
            local ev = ReplicatedStorage:FindFirstChild("Remotes", true)
                and ReplicatedStorage.Remotes:FindFirstChild("Killers", true)
                and ReplicatedStorage.Remotes.Killers:FindFirstChild("Masked", true)
                and ReplicatedStorage.Remotes.Killers.Masked:FindFirstChild("Deactivatepower")
            if ev then
                pcall(function() ev:FireServer() end)
                VD_Notify("Select Masked", "Deactivated", 2)
            else ForceNotify("Select Masked", "Deactivatepower remote not found", 2) end
        end

        W.FullESP = W.FullESP or {
            Survivor = false, Killer = false,
            Generator = false, Pallet = false, Window = false, SCP = false,
            Distance = 500,
        }
        W.FullESPStatus = W.FullESPStatus or {
            Enabled = false,
            ShowName = true, ShowDistance = true, ShowHealth = false,
            ShowAvatar = true, ShowAction = true, Radius = 500,
        }
        W.FullESPColors = W.FullESPColors or {
            Survivor  = Color3.fromRGB(0, 255, 255), Killer    = Color3.fromRGB(255, 0, 0),
            Generator = Color3.fromRGB(0, 255, 0), Window    = Color3.fromRGB(255, 255, 255),
            Pallet    = Color3.fromRGB(255, 255, 255), SCP       = Color3.fromRGB(255, 165, 0),
        }
        local FESP  = W.FullESP
        local FESPS = W.FullESPStatus
        local FESPC = W.FullESPColors

        -- Fixed colors for the requested ESP categories. Window keeps its original RGB cycle.
        FESPC.Survivor  = Color3.fromRGB(0, 255, 255) -- Cyan
        FESPC.Killer    = Color3.fromRGB(255, 0, 0)   -- Red
        FESPC.Generator = Color3.fromRGB(0, 255, 0)   -- Green
        FESPC.Pallet    = Color3.fromRGB(255, 255, 255) -- White
        FESPC.SCP       = Color3.fromRGB(255, 165, 0) -- Orange

        local function GetESPColor(category)
            -- These categories use a fixed color instead of cycling through RGB palettes.
            if category ~= "Window" then
                return FESPC[category] or Color3.new(1, 1, 1)
            end

            -- Preserve the original RGB animation for Window ESP only.
            local palette = {
                Color3.fromRGB(0, 255, 255),
                Color3.fromRGB(70, 130, 255),
                Color3.fromRGB(190, 90, 255),
            }
            local phase = (tick() * 0.65) % #palette
            local index = math.floor(phase) + 1
            local nextIndex = (index % #palette) + 1
            return palette[index]:Lerp(palette[nextIndex], phase - math.floor(phase))
        end

        do
            local ESPObjects = {}
            local StatusESP  = {}
            local CachedSCP     = {}
            local CachedGen     = {}
            local CachedPallet  = {}
            local CachedWindow  = {}
            local WindowObjects = {}

            local function CacheObject(obj)
                if not obj then return end
                local ln = string.lower(obj.Name)
                if string.find(ln, "scp", 1, true) then CachedSCP[obj] = true end
                if obj.Name == "Generator" then
                    CachedGen[obj] = true
                elseif obj.Name == "Pallet" or obj.Name == "Palletwrong" then
                    CachedPallet[obj] = true
                end
            end

            for _, obj in ipairs(Workspace:GetDescendants()) do CacheObject(obj) end
            Workspace.DescendantAdded:Connect(CacheObject)
            Workspace.DescendantRemoving:Connect(function(obj)
                CachedSCP[obj] = nil; CachedGen[obj] = nil
                CachedPallet[obj] = nil; CachedWindow[obj] = nil
                if ESPObjects[obj] then pcall(function() ESPObjects[obj]:Destroy() end); ESPObjects[obj] = nil end
                if StatusESP[obj] then pcall(function() StatusESP[obj]:Destroy() end); StatusESP[obj] = nil end
            end)

            local function RemoveESP(obj)
                if not obj then return end
                if ESPObjects[obj] then
                    pcall(function() ESPObjects[obj]:Destroy() end)
                    ESPObjects[obj] = nil
                end
            end

            local function CreateESP(obj, color)
                if not obj or not obj.Parent then return end
                if ESPObjects[obj] then
                    ESPObjects[obj].FillColor = color
                    ESPObjects[obj].OutlineColor = color
                    return
                end
                local h = Instance.new("Highlight")
                h.FillColor = color
                h.OutlineColor = color
                h.FillTransparency = 0.9
                h.OutlineTransparency = 0.3
                h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                h.Parent = obj
                ESPObjects[obj] = h
                obj.AncestryChanged:Connect(function(_, parent)
                    if not parent then RemoveESP(obj) end
                end)
            end

            local function RemoveStatusESP(char)
                if StatusESP[char] then
                    pcall(function() StatusESP[char]:Destroy() end)
                    StatusESP[char] = nil
                end
            end

            local function StatusESP_GetAction(char, hum)
                if not char or not hum then return "IDLE", Color3.fromRGB(150, 150, 150) end
                if hum.Health <= 0 then return "DEAD", Color3.fromRGB(200, 60, 60) end
                if char:GetAttribute("IsHooked") or char:GetAttribute("isHooked") or char:GetAttribute("Hooked") then
                    return "HOOKED", Color3.fromRGB(255, 60, 60)
                end
                if char:GetAttribute("IsCarried") or char:GetAttribute("isCarried") or char:GetAttribute("Carried") then
                    return "CARRIED", Color3.fromRGB(255, 100, 100)
                end
                local state = char:GetAttribute("State")
                if state == "Downed" or char:GetAttribute("Knocked") == true
                   or char:GetAttribute("IsDown") == true or char:GetAttribute("Downed") == true then
                    return "DOWNED", Color3.fromRGB(255, 130, 60)
                end
                local ci = char:FindFirstChild("CheckInterractable")
                if ci then
                    if ci:GetAttribute("isRepairing") then return "REPAIR", Color3.fromRGB(255, 220, 60) end
                    if ci:GetAttribute("isHealing") then return "HEAL", Color3.fromRGB(80, 220, 120) end
                    if ci:GetAttribute("isVaulting") then return "VAULT", Color3.fromRGB(120, 200, 255) end
                    if ci:GetAttribute("isSliding") then return "SLIDE", Color3.fromRGB(150, 180, 255) end
                    if ci:GetAttribute("isDroppingPallet") then return "PALLET", Color3.fromRGB(255, 165, 60) end
                    if ci:GetAttribute("isUnhooking") then return "UNHOOK", Color3.fromRGB(180, 120, 255) end
                    if ci:GetAttribute("isExiting") then return "EXIT", Color3.fromRGB(80, 255, 180) end
                end
                local root = char:FindFirstChild("HumanoidRootPart")
                if root then
                    local vel = root.AssemblyLinearVelocity
                    local speed = Vector3.new(vel.X, 0, vel.Z).Magnitude
                    if speed > 20 then return "SPRINT", Color3.fromRGB(120, 255, 200) end
                    if speed > 2 then return "MOVE", Color3.fromRGB(200, 200, 220) end
                end
                return "IDLE", Color3.fromRGB(150, 150, 150)
            end

            local function CreateStatusESP(plr, char, root)
                if not FESPS.Enabled then RemoveStatusESP(char); return end
                if not root then return end
                local head = char:FindFirstChild("Head")
                local hum = char:FindFirstChildOfClass("Humanoid")
                if not head or not hum then return end

                local isDown = hum.Health <= 0 or hum.Health < 2
                    or char:GetAttribute("Downed") == true
                    or char:GetAttribute("IsDown") == true
                    or char:GetAttribute("Knocked") == true

                local dist = (head.Position - root.Position).Magnitude
                if dist > FESPS.Radius then RemoveStatusESP(char); return end

                local accentColor = Color3.fromRGB(255, 255, 255)
                if TeamIs(plr, "Killer") then accentColor = GetESPColor("Killer")
                elseif TeamIs(plr, "Survivor") then accentColor = GetESPColor("Survivor") end
                if isDown then accentColor = Color3.fromRGB(255, 60, 60) end

                local hpPct = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                local hpColor
                if hpPct > 0.6 then hpColor = Color3.fromRGB(80, 220, 120)
                elseif hpPct > 0.3 then hpColor = Color3.fromRGB(255, 200, 60)
                else hpColor = Color3.fromRGB(255, 80, 80) end

                local actionText, actionColor = StatusESP_GetAction(char, hum)

                local bb = StatusESP[char]
                if not bb or not bb.Parent then
                    bb = Instance.new("BillboardGui")
                    bb.Name = "GlutoStatusESP"
                    bb.AlwaysOnTop = true
                    bb.LightInfluence = 0
                    bb.Adornee = head
                    bb.StudsOffset = Vector3.new(0, 2.5, 0)
                    bb.Size = UDim2.fromOffset(260, 40)
                    bb.Parent = char

                    local scaleObj = Instance.new("UIScale")
                    scaleObj.Name = "DistScale"
                    scaleObj.Scale = 1
                    scaleObj.Parent = bb

                    local nameLbl = Instance.new("TextLabel")
                    nameLbl.Name = "NameLbl"
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Size = UDim2.new(1, 0, 0, 16)
                    nameLbl.Position = UDim2.new(0, 0, 0, 0)
                    nameLbl.Font = Enum.Font.GothamBold
                    nameLbl.TextSize = 13
                    nameLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
                    nameLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                    nameLbl.TextStrokeTransparency = 0.2
                    nameLbl.TextXAlignment = Enum.TextXAlignment.Center
                    nameLbl.TextYAlignment = Enum.TextYAlignment.Center
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.Parent = bb

                    local pill = Instance.new("Frame")
                    pill.Name = "Pill"
                    pill.AnchorPoint = Vector2.new(0.5, 0)
                    pill.Position = UDim2.new(0.5, 0, 0, 18)
                    pill.Size = UDim2.fromOffset(120, 22)
                    pill.BackgroundColor3 = Color3.fromRGB(12, 12, 16)
                    pill.BackgroundTransparency = 0.15
                    pill.BorderSizePixel = 0
                    pill.Parent = bb
                    Instance.new("UICorner", pill).CornerRadius = UDim.new(1, 0)

                    local pillStroke = Instance.new("UIStroke", pill)
                    pillStroke.Name = "PillStroke"
                    pillStroke.Color = accentColor
