local VeilV12State = {
    Charging = false,
    TouchInput = nil,
    AttackCooldown = false,
    SuppressNextThrow = false,
    SuppressUntil = 0,
    LastPredictedPos = nil,
    LastPredictedUntil = 0,
    Hooked = false,
    CurrentGUID = nil,
    CurrentTargetPos = nil,

    HomingThread = nil,
    HomingActive = false,

    LockedPlayer = nil,
};
local VeilV12VelocityCache = {};
