local function VeilV12HideAllMarkers()
    for _, circle in pairs(VeilV12CirclePool) do circle.Visible = false end;
    for _, text in pairs(VeilV12TextPool) do text.Visible = false end;
    if VeilV12Draw.TargetMarker then VeilV12Draw.TargetMarker.Visible = false end;
end;

local VeilV12StopHoming;

local function VeilV12HideDrawings()
    if VeilV12StopHoming then VeilV12StopHoming() end;
    if VeilV12Draw.FOVCircle then VeilV12Draw.FOVCircle.Visible = false end;
    if VeilV12Draw.Tracer then VeilV12Draw.Tracer.Visible = false end;
    if VeilV12Draw.GuiFOV then VeilV12Draw.GuiFOV.Visible = false end;
    if VeilV12Draw.GuiTracer then VeilV12Draw.GuiTracer.Visible = false end;
    VeilV12Draw.Highlight.Parent = nil;
    VeilV12HideAllMarkers();
end;

local function VeilV12GenerateGUID()
    local template = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx";
    return string.gsub(template, "[xy]", function(c)
        local v = (c == "x") and math.random(0, 15) or math.random(8, 11);
        return string.format("%x", v);
    end);
end;

local function VeilV12TargetPart(character)
    if not character then return nil end;
    if VD.VeilTargetPart == "Head" then return character:FindFirstChild("Head") end;
    if VD.VeilTargetPart == "Root" then return character:FindFirstChild("HumanoidRootPart") end;
    return character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("HumanoidRootPart");
end;

local function VeilV12Velocity(part, playerName)
    if not part then return Vector3.zero end;
    local now = os.clock();
    local assemblyVelocity = Vector3.zero;
    pcall(function() assemblyVelocity = part.AssemblyLinearVelocity end);
    local cache = VeilV12VelocityCache[playerName];
    if not cache then
        VeilV12VelocityCache[playerName] = { LastPos = part.Position, LastTime = now, Velocity = assemblyVelocity };
        return assemblyVelocity;
    end;
    local dt = now - cache.LastTime;
    local measured = Vector3.zero;
    if dt > 0.01 then measured = (part.Position - cache.LastPos) / dt end;
    if measured.Magnitude > 250 then measured = assemblyVelocity end;
    local chosen = measured.Magnitude > 0.05 and measured or assemblyVelocity;
    if chosen.Magnitude < 250 then cache.Velocity = cache.Velocity:Lerp(chosen, 0.45) end;
    cache.LastPos = part.Position;
    cache.LastTime = now;
    return cache.Velocity;
end;

local function VeilV12Ping()
    if not VD.VeilPingCompensation then return 0 end;
    local ping = 0;
    pcall(function()
        local stat = game:GetService("Stats").Network.ServerStatsItem["Data Ping"];
        ping = stat:GetValue() / 1000;
    end);
    return math.clamp(ping, 0, 0.5);
end;

local function VeilV12GetAllTargets()
    local localPlayer = game:GetService("Players").LocalPlayer;
    local localCharacter = localPlayer.Character;
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart");
    local camera = workspace.CurrentCamera;
    if not localRoot or not camera then return {} end;

    local targets = {};
    local center = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y * 0.5);
    local closeRange = math.max(0, tonumber(VD.VeilCloseLockRange) or 60);
    local bias = math.max(0, tonumber(VD.VeilDistanceBias) or 0.75);

    for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
        if player ~= localPlayer and player.Team and player.Team.Name == "Survivors" and player.Character then
            local character = player.Character;
            local humanoid = character:FindFirstChildOfClass("Humanoid");
            local part = VeilV12TargetPart(character);
            if humanoid and humanoid.Health > 0 and part then
                local distance3D = (part.Position - localRoot.Position).Magnitude;
                if distance3D <= VD.VeilMaxDist then
                    local screen, onScreen = camera:WorldToViewportPoint(part.Position);
                    local screenPos = Vector2.new(screen.X, screen.Y);
                    local screenDistance = (screenPos - center).Magnitude;
                    local isClose = distance3D <= closeRange;
                    local inFOV = onScreen and screenDistance <= VD.VeilFOV;

                    if inFOV or (not VD.VeilStrictFOV and isClose) then
                        local score = (onScreen and screenDistance or (screenDistance + 2000)) + distance3D * bias;
                        if isClose then score = score - 1500 end;
                        table.insert(targets, {
                            Player = player,
                            Part = part,
                            Distance = distance3D,
                            ScreenPos = screenPos,
                            ScreenDistance = screenDistance,
                            OnScreen = onScreen,
                            IsClose = isClose,
                            Score = score,
                            Humanoid = humanoid
                        });
                    end;
                end;
            end;
        end;
    end;

    table.sort(targets, function(a, b)
        return a.Score < b.Score;
    end);

    return targets;
end;

local function VeilV12ClosestTarget(preferPlayer)
    local targets = VeilV12GetAllTargets();
    local best = targets[1];
    if not best then return nil end;

    local wanted = preferPlayer or (VD.VeilStickyLock and VeilV12State.LockedPlayer or nil);
    if wanted then
        for _, t in ipairs(targets) do
            if t.Player == wanted then
                return t; 

            end;
        end;
    end;
    return best;
end;

local function VeilV12BallisticDirection(startPosition, targetPosition, targetVelocity)
    local speed = math.max(1, tonumber(VD.VeilSpearSpeed) or 165);
    local gravity = VD.VeilAutoGravity and math.max(0, (workspace.Gravity or 196.2) * 0.5) or math.max(0, tonumber(VD.VeilGravity) or 0);
    local lead = VD.VeilAutoPredict and (tonumber(VD.VeilLeadMultiplier) or 1) or 0;
    local predicted = targetPosition;
    local travelTime = (targetPosition - startPosition).Magnitude / speed;
    local direction = (targetPosition - startPosition).Unit;
    for _ = 1, 4 do
        predicted = targetPosition + targetVelocity * travelTime * lead;
        local offset = predicted - startPosition;
        local distance = offset.Magnitude;
        if distance <= VD.VeilCloseRange then
            return offset.Unit, predicted;
        end;
        local horizontal = Vector3.new(offset.X, 0, offset.Z);
        local range = horizontal.Magnitude;
        if range < 0.05 or gravity <= 0 then
            direction = offset.Unit;
        else
            local speedSquared = speed * speed;
            local discriminant = speedSquared * speedSquared - gravity * (gravity * range * range + 2 * offset.Y * speedSquared);
            if discriminant <= 0 then
                direction = offset.Unit;
            else
                local tangent = (speedSquared - math.sqrt(discriminant)) / (gravity * range);
                local cosine = 1 / math.sqrt(1 + tangent * tangent);
                direction = (horizontal.Unit * cosine + Vector3.new(0, tangent * cosine, 0)).Unit;
            end;
        end;
        travelTime = distance / speed;
    end;
    return direction, predicted;
end;

VeilV12StopHoming = function()
    if VeilV12State.HomingThread then
        pcall(task.cancel, VeilV12State.HomingThread);
        VeilV12State.HomingThread = nil;
    end;
    VeilV12State.HomingActive = false;
    VeilV12State.LockedPlayer = nil;
end;

local function VeilV12StartHoming(initialTarget, character, startPosition, initialDirection, launchDistance)
    VeilV12StopHoming();

    local remotes        = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes");
    local mechanics      = remotes and remotes:FindFirstChild("Mechanics");
    local visualizeEvent = mechanics and mechanics:FindFirstChild("visualize");
    local visualizeStop  = mechanics and mechanics:FindFirstChild("visualizeStop");

    if not visualizeEvent or not firesignal then
        return false;
    end;

    local speed     = math.max(1, tonumber(VD.VeilSpearSpeed) or 165);
    local duration  = tonumber(VD.VeilHomingDuration) or 1.4;
    local rate      = math.max(0.02, tonumber(VD.VeilHomingRate) or 0.04);
    local hitDist   = tonumber(VD.VeilHomingHitDist) or 3;

    VeilV12State.HomingActive = true;

    VeilV12State.HomingThread = task.spawn(function()

        local useArc = VD.VeilLongRangeArc and (tonumber(launchDistance) or 0) > (tonumber(VD.VeilArcStartRange) or 65);
        local arcDelay = useArc and math.max(0, tonumber(VD.VeilArcHomingDelay) or 0.18) or 0;
        local launchDirection = initialDirection or workspace.CurrentCamera.CFrame.LookVector;
        if arcDelay > 0 then task.wait(arcDelay) end;

        local startTime   = os.clock();
        local lastTick    = startTime;
        local simPos      = startPosition + launchDirection * speed * arcDelay;
        if useArc then
            local gravity = VD.VeilAutoGravity and math.max(0, (workspace.Gravity or 196.2) * 0.5) or math.max(0, tonumber(VD.VeilGravity) or 0);
            simPos = simPos - Vector3.new(0, 0.5 * gravity * arcDelay * arcDelay, 0);
        end;
        local currentGUID = nil;
        local lastTarget  = initialTarget;

        while VeilV12State.HomingActive and (os.clock() - startTime) < duration do
            local now = os.clock();
            local dt  = math.max(0, now - lastTick);
            lastTick  = now;

            local lockPlayer = (initialTarget and initialTarget.Player) or VeilV12State.LockedPlayer;
            local live = VeilV12ClosestTarget(lockPlayer) or lastTarget;

            if live and live.Part and live.Part.Parent then
                lastTarget = live;
                VeilV12State.LockedPlayer = live.Player;

                local velocity    = VeilV12Velocity(live.Part, live.Player.Name);
                local distance    = (live.Part.Position - simPos).Magnitude;
                local leadTime    = distance / speed + VeilV12Ping() + (tonumber(VD.VeilExtraLeadTime) or 0);
                local predicted   = live.Part.Position + velocity * leadTime * (tonumber(VD.VeilLeadMultiplier) or 1);

                local direction = (predicted - simPos);
                if direction.Magnitude < 0.01 then
                    direction = (live.Part.Position - simPos);
                end;
                direction = direction.Unit;

                if distance <= math.max(4, hitDist * 2) then
                    direction = (live.Part.Position - simPos).Unit;
                end;

                simPos = simPos + direction * speed * dt;

                if currentGUID and visualizeStop then
                    pcall(function()
                        firesignal(visualizeStop.OnClientEvent, currentGUID, simPos);
                    end);
                end;

                local newGUID = VeilV12GenerateGUID();
                pcall(function()
                    firesignal(visualizeEvent.OnClientEvent,
                        character,
                        direction,
                        speed,
                        0.1,
                        newGUID
                    );
                end);

                currentGUID = newGUID;
                VeilV12State.CurrentGUID = newGUID;
                VeilV12State.CurrentTargetPos = predicted;
                VeilV12State.LastPredictedPos = predicted;
                VeilV12State.LastPredictedUntil = now + 0.2;

                if (simPos - live.Part.Position).Magnitude <= hitDist then
                    break;
                end;
            else
                local dir = workspace.CurrentCamera.CFrame.LookVector;
                simPos = simPos + dir * speed * dt;

                if currentGUID and visualizeStop then
                    pcall(function()
                        firesignal(visualizeStop.OnClientEvent, currentGUID, simPos);
                    end);
                end;
                currentGUID = nil;
                break;
            end;

            task.wait(rate);
        end

        if currentGUID and visualizeStop then
            pcall(function()
                firesignal(visualizeStop.OnClientEvent, currentGUID, simPos);
            end);
        end

        VeilV12State.CurrentGUID = nil;
        VeilV12State.CurrentTargetPos = nil;
        VeilV12State.HomingActive = false;
    end);

    return true;
end;

local function VeilV12Fire()
    if not VD.VeilEnabled or VeilV12State.AttackCooldown then return end;

    local localPlayer = game:GetService("Players").LocalPlayer;
    local character   = localPlayer.Character;
    if not character or character:GetAttribute("spearmode") ~= true then return end;
    local currentCamera = workspace.CurrentCamera;
    if not currentCamera then return end;

    VeilV12State.AttackCooldown = true;
    task.delay(0.18, function() VeilV12State.AttackCooldown = false end);

    local startPart = character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart");
    if not startPart then return end;

    local startPosition = startPart.Position;

    VeilV12State.LockedPlayer = nil;
    local target        = VeilV12ClosestTarget();
    local aimDirection  = currentCamera.CFrame.LookVector;
    local targetPosition = nil;

    if target and target.Part then
        VeilV12State.LockedPlayer = target.Player;
        local velocity = VeilV12Velocity(target.Part, target.Player.Name);

        local dist = (target.Part.Position - startPosition).Magnitude;
        local useArc = VD.VeilLongRangeArc and dist > (tonumber(VD.VeilArcStartRange) or 65);

        if VD.VeilDirectAim and not useArc then
            local leadTime = dist / math.max(1, VD.VeilSpearSpeed) + VeilV12Ping() + (tonumber(VD.VeilExtraLeadTime) or 0);
            local predicted = target.Part.Position + velocity * leadTime * (tonumber(VD.VeilLeadMultiplier) or 1);
            if dist <= math.max(4, tonumber(VD.VeilHomingHitDist) or 4) * 2 then
                predicted = target.Part.Position;
            end;
            aimDirection = (predicted - startPosition).Unit;
            VeilV12State.LastPredictedPos = predicted;
        else
            aimDirection, VeilV12State.LastPredictedPos =
                VeilV12BallisticDirection(startPosition, target.Part.Position, velocity);
        end;

        VeilV12State.LastPredictedUntil = os.clock() + 1.25;
        targetPosition = VeilV12State.LastPredictedPos or target.Part.Position;
    else
        VeilV12State.LastPredictedPos   = nil;
        VeilV12State.LastPredictedUntil = 0;
    end;

    local visualizeEvent, visualizeStopEvent;
    pcall(function()
        local remotes   = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes");
        local mechanics = remotes and remotes:FindFirstChild("Mechanics");
        visualizeEvent      = mechanics and mechanics:FindFirstChild("visualize");
        visualizeStopEvent  = mechanics and mechanics:FindFirstChild("visualizeStop");

        if visualizeEvent and firesignal then
            if VeilV12State.CurrentGUID and visualizeStopEvent and VeilV12State.CurrentTargetPos then
                pcall(function()
                    firesignal(visualizeStopEvent.OnClientEvent, VeilV12State.CurrentGUID, VeilV12State.CurrentTargetPos);
                end);
            end;

            local newGUID = VeilV12GenerateGUID();
            VeilV12State.CurrentGUID      = newGUID;
            VeilV12State.CurrentTargetPos = targetPosition or (startPosition + aimDirection * 100);

            firesignal(visualizeEvent.OnClientEvent,
                character,
                aimDirection,
                VD.VeilSpearSpeed,
                0.5,
                newGUID
            );

            task.delay(1.5, function()
                if visualizeStopEvent and VeilV12State.CurrentGUID == newGUID and not VeilV12State.HomingActive then
                    pcall(function()
                        firesignal(visualizeStopEvent.OnClientEvent, newGUID, VeilV12State.CurrentTargetPos);
                    end);
                    VeilV12State.CurrentGUID = nil;
                    VeilV12State.CurrentTargetPos = nil;
                end;
            end);
        end;
    end);

    VeilV12State.SuppressNextThrow = true;
    VeilV12State.SuppressUntil = os.clock() + 0.35;

    pcall(function()
        local remotes    = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes");
        local killers    = remotes and remotes:FindFirstChild("Killers");
        local veil       = killers and killers:FindFirstChild("Veil");
        local spearThrow = veil and veil:FindFirstChild("Spearthrow");
        if spearThrow and spearThrow:IsA("RemoteEvent") then
            spearThrow:FireServer(aimDirection, VD.VeilSpearSpeed, startPosition);
        end
    end);

    task.delay(0.4, function() VeilV12State.SuppressNextThrow = false end);

    if VD.VeilRunToTarget and target and target.Part then
        task.spawn(function()
            VeilV12StartHoming(target, character, startPosition, aimDirection, target.Distance);
        end);
    end;
end;

if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
    pcall(function()
        local oldNamecall;
        oldNamecall = hookmetamethod(game, "__namecall", (newcclosure or function(fn) return fn end)(function(self, ...) 
            if getnamecallmethod() == "FireServer" and self.Name == "Spearthrow" then
                if not VD.VeilV3Enabled and VeilV12State.SuppressNextThrow and os.clock() <= VeilV12State.SuppressUntil then
                    if type(checkcaller) == "function" and not checkcaller() then
                        VeilV12State.SuppressNextThrow = false;
                        return nil;
                    end;
                end;
            end;
            return oldNamecall(self, ...);
        end));
        VeilV12State.Hooked = true;
    end);
end;

local VeilV12UserInput = game:GetService("UserInputService");
VeilV12UserInput.InputBegan:Connect(function(input, gameProcessed)
    local isTouch = input.UserInputType == Enum.UserInputType.Touch;
    if gameProcessed and not isTouch then return end;
    local character = game:GetService("Players").LocalPlayer.Character;
    if not VD.VeilEnabled or not character or character:GetAttribute("spearmode") ~= true then return end;
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        VeilV12State.Charging = true;
    elseif isTouch then
        local playerGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui");
        local slasher = playerGui and playerGui:FindFirstChild("Slasher-mob");
        local controls = slasher and slasher:FindFirstChild("Controls");
        local attack = controls and controls:FindFirstChild("attack");
        if attack and attack.Visible then
            local position = input.Position;
            local absolutePosition, absoluteSize = attack.AbsolutePosition, attack.AbsoluteSize;
            if position.X >= absolutePosition.X and position.X <= absolutePosition.X + absoluteSize.X and position.Y >= absolutePosition.Y and position.Y <= absolutePosition.Y + absoluteSize.Y then
                VeilV12State.Charging = true;
                VeilV12State.TouchInput = input;
            end;
        end;
    end;
end);
VeilV12UserInput.InputEnded:Connect(function(input)
    if VeilV12State.Charging and (input == VeilV12State.TouchInput or input.UserInputType == Enum.UserInputType.MouseButton1) then
        VeilV12State.Charging = false;
        if VeilV12State.TouchInput == input then VeilV12State.TouchInput = nil end;
        VeilV12Fire();
    end;
end);

game:GetService("RunService").RenderStepped:Connect(function()
    local camera = workspace.CurrentCamera;
    local localPlayer = game:GetService("Players").LocalPlayer;
    local character = localPlayer.Character;
    local spearMode = character and character:GetAttribute("spearmode") == true;
    local localRoot = character and character:FindFirstChild("HumanoidRootPart");

    if not VD.VeilEnabled or not spearMode or not localRoot then
        VeilV12HideDrawings();
        return;
    end;

    pcall(VeilV12EnsureGuiFOV);
    local fovR = tonumber(VD.VeilFOV) or 300;
    if VD.VeilShowFOV then
        if VeilV12Draw.FOVCircle then
            VeilV12Draw.FOVCircle.Visible = true;
            VeilV12Draw.FOVCircle.Radius = fovR;
            VeilV12Draw.FOVCircle.Position = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y * 0.5);
            VeilV12Draw.FOVCircle.Color = Color3.fromRGB(220, 70, 70);
            VeilV12Draw.FOVCircle.Thickness = 2;
        end
        if VeilV12Draw.GuiFOV then
            local diam = math.floor(fovR * 2);
            VeilV12Draw.GuiFOV.Size = UDim2.fromOffset(diam, diam);
            VeilV12Draw.GuiFOV.Visible = true;
            if VeilV12Draw.GuiFOVStroke then
                VeilV12Draw.GuiFOVStroke.Color = Color3.fromRGB(220, 70, 70);
                VeilV12Draw.GuiFOVStroke.Thickness = 2.5;
            end
        end
    else
        if VeilV12Draw.FOVCircle then VeilV12Draw.FOVCircle.Visible = false end;
        if VeilV12Draw.GuiFOV then VeilV12Draw.GuiFOV.Visible = false end;
    end;

    local targets = VeilV12GetAllTargets();
    local primaryTarget = targets[1];

    VeilV12HideAllMarkers();

    if VD.VeilShowTracker then
        for i, target in ipairs(targets) do
            local circle = VeilV12GetCircleFromPool(i);
            local text = VeilV12GetTextFromPool(i);

            local dynamicRadius = math.clamp(VD.VeilMarkerSize / target.Distance, 8, 35);

            circle.Position = target.ScreenPos;
            circle.Radius = dynamicRadius;
            circle.Color = Color3.fromRGB(255, 90, 90);
            circle.Visible = true;

            local healthPct = math.floor((target.Humanoid.Health / target.Humanoid.MaxHealth) * 100);
            text.Position = target.ScreenPos - Vector2.new(0, dynamicRadius + 15);
            text.Text = string.format("%s [%d%%] [%dm]", target.Player.Name, healthPct, math.floor(target.Distance));
            text.Color = Color3.fromRGB(255, 180, 180);
            text.Visible = true;
        end;
    end;

    if primaryTarget then
        local targetCircle = VeilV12GetCircleFromPool(#targets + 1);
        local dynamicRadius = math.clamp(VD.VeilMarkerSize / primaryTarget.Distance, 8, 35);

        targetCircle.Position = primaryTarget.ScreenPos;
        targetCircle.Radius = dynamicRadius + 4;
        targetCircle.Color = Color3.fromRGB(255, 0, 0);
        targetCircle.Visible = true;

        if primaryTarget.Part and primaryTarget.Part.Parent then
            VeilV12Draw.Highlight.Parent = primaryTarget.Part.Parent;
        end;

        if VeilV12Draw.Tracer then
            local bottomCenter = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y);
            VeilV12Draw.Tracer.From = bottomCenter;
            VeilV12Draw.Tracer.To = primaryTarget.ScreenPos;
            VeilV12Draw.Tracer.Visible = true;
        end;

        if VeilV12State.Charging and character then
            local startPart = character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart");
            if startPart then
                local velocity = VeilV12Velocity(primaryTarget.Part, primaryTarget.Player.Name);
                local _, predicted = VeilV12BallisticDirection(startPart.Position, primaryTarget.Part.Position, velocity);
                VeilV12State.LastPredictedPos = predicted;
                VeilV12State.LastPredictedUntil = os.clock() + 0.12;
            end;
        end;
    else
        VeilV12Draw.Highlight.Parent = nil;
        if VeilV12Draw.Tracer then VeilV12Draw.Tracer.Visible = false end;
    end;

    if VeilV12Draw.Tracer and VeilV12State.LastPredictedPos and os.clock() <= VeilV12State.LastPredictedUntil and not primaryTarget then
        local screen, onScreen = camera:WorldToViewportPoint(VeilV12State.LastPredictedPos);
        local center = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y * 0.5);
        local bottomCenter = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y);
        if onScreen then
            VeilV12Draw.Tracer.From = bottomCenter;
            VeilV12Draw.Tracer.To = Vector2.new(screen.X, screen.Y);
        else
            local dx, dy = screen.X - center.X, screen.Y - center.Y;
            local scale = math.min((camera.ViewportSize.X * 0.5 - 10) / math.max(math.abs(dx), 0.001), (camera.ViewportSize.Y * 0.5 - 10) / math.max(math.abs(dy), 0.001));
            VeilV12Draw.Tracer.From = bottomCenter;
            VeilV12Draw.Tracer.To = Vector2.new(center.X + dx * scale, center.Y + dy * scale);
        end;
        VeilV12Draw.Tracer.Visible = true;
    end;
end);

        end

        W.MAWWW_VeilV1_API = {
            setEnabled = function(v)
                VD.VeilEnabled = v and true or false
                if not VD.VeilEnabled then
                    VeilV12State.Charging = false
                    VeilV12State.TouchInput = nil
                    VeilV12State.LockedPlayer = nil
                    VeilV12HideDrawings()
                end
            end,
            hide = function()
                VeilV12State.Charging = false
                VeilV12State.TouchInput = nil
                VeilV12State.LockedPlayer = nil
                VeilV12HideDrawings()
            end,
            update = function()

                return VD.VeilEnabled == true
            end,
        }

        do
            local W = getgenv()
            local VeilV2Connection
            local VeilV2HookState = { remoteHooked = false }

            VD.VeilV2Enabled          = VD.VeilV2Enabled or false
            VD.VeilV2ShowFOV          = VD.VeilV2ShowFOV ~= false
            VD.VeilV2ShowTracker      = VD.VeilV2ShowTracker or false
            VD.VeilV2AutoPredict      = VD.VeilV2AutoPredict ~= false
            VD.VeilV2FOV              = VD.VeilV2FOV or 150
            VD.VeilV2MaxDist          = VD.VeilV2MaxDist or 500
            VD.VeilV2SpearSpeed       = VD.VeilV2SpearSpeed or 165
            VD.VeilV2Gravity          = VD.VeilV2Gravity or 103
            VD.VeilV2AuraSpearSpeed   = VD.VeilV2AuraSpearSpeed or 165
            VD.VeilV2AuraSpearGravity = VD.VeilV2AuraSpearGravity or 96.5
            VD.VeilV2LeadMultiplier   = VD.VeilV2LeadMultiplier or 1.4

                local VeilState = { target = nil, lookVector = nil, velHistory = {} }
                local VeilVisuals = { FOVCrossLines = {}, FOVTicks = {} }

                -- Create each Drawing object independently. Some executors expose Drawing
                -- differently, and one unsupported property must not disable targeting.
                local function Veil_NewDrawing(kind, props)
                    local drawingNew
                    local okGet = pcall(function() drawingNew = Drawing.new end)
                    if not okGet or type(drawingNew) ~= "function" then return nil end
                    local ok, obj = pcall(drawingNew, kind)
                    if not ok or not obj then return nil end
                    for property, value in pairs(props or {}) do
                        pcall(function() obj[property] = value end)
                    end
                    return obj
                end

                do
                    local V = VeilVisuals
                    local ACCENT = (W.WISNU_ACCENT or _G.GLUTO_ACCENT or Color3.fromRGB(72, 166, 255))
                    local BLACK = Color3.fromRGB(0, 0, 0)
                    local WHITE = Color3.fromRGB(255, 255, 255)
                    V.FOVOuterRing = Veil_NewDrawing("Circle", { Color = BLACK, Thickness = 3, Filled = false, Transparency = 0.4, Visible = false, NumSides = 90 })
                    V.FOVMainRing  = Veil_NewDrawing("Circle", { Color = ACCENT, Thickness = 1.6, Filled = false, Transparency = 0.85, Visible = false, NumSides = 90 })
                    V.FOVInnerRing = Veil_NewDrawing("Circle", { Color = ACCENT, Thickness = 1, Filled = false, Transparency = 0.35, Visible = false, NumSides = 90 })
                    for i = 1, 4 do
                        V.FOVCrossLines[i] = Veil_NewDrawing("Line", { Color = WHITE, Thickness = 1.5, Transparency = 0.9, Visible = false })
                        V.FOVTicks[i] = Veil_NewDrawing("Line", { Color = ACCENT, Thickness = 2.2, Transparency = 0.95, Visible = false })
                    end
                    V.TrackerOuterRing = Veil_NewDrawing("Circle", { Color = BLACK, Thickness = 3, Filled = false, Transparency = 0.3, NumSides = 40, Visible = false })
                    V.TrackerMainRing  = Veil_NewDrawing("Circle", { Color = ACCENT, Thickness = 1.6, Filled = false, Transparency = 0.9, NumSides = 40, Visible = false })
                    V.TrackerDotFill   = Veil_NewDrawing("Circle", { Color = ACCENT, Thickness = 1, Filled = true, Transparency = 0.9, Radius = 3, NumSides = 20, Visible = false })
                    V.TrackerDotOutline= Veil_NewDrawing("Circle", { Color = BLACK, Thickness = 3, Filled = false, Transparency = 0.3, Radius = 6, NumSides = 20, Visible = false })
                    V.TrackerLine      = Veil_NewDrawing("Line", { Color = ACCENT, Thickness = 1.5, Transparency = 0.6, Visible = false })
                end
                local function Veil_IsSurvivorVeil(p)
                    if not p or not p.Team or not p.Team.Name then return false end
                    return string.find(string.lower(p.Team.Name), "survivor", 1, true) ~= nil
                end
                local function Veil_solvePitch(p, d, dy)
                    d = math.max(d, 0.1)
                    local s2 = p.v0 * p.v0
                    local root = s2 * s2 - p.g * (p.g * d * d + 2 * dy * s2)
                    if root < 0 then root = 0 end
                    local tanTheta = (s2 - math.sqrt(root)) / (p.g * d)
                    local theta = math.atan(tanTheta)
                    local t = d / (p.v0 * math.cos(theta))
                    return theta, t
                end
                local function Veil_getCharacterVelocity(char)
                    local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
                    if not root or not root:IsA("BasePart") then return Vector3.zero end
                    local now = os.clock()
                    local last = VeilState.velHistory[char]
                    local measured = Vector3.zero
                    if last and now - last.t > 0.02 then
                        measured = (root.Position - last.pos) / (now - last.t)
                        if measured.Magnitude > 150 then measured = last.smooth or Vector3.zero end
                    end
                    local smooth = last and last.smooth or measured
                    smooth = smooth:Lerp(measured, 0.65)
                    VeilState.velHistory[char] = { pos = root.Position, t = now, smooth = smooth }
                    if smooth.Magnitude < 1 then return Vector3.zero end
                    return Vector3.new(smooth.X, 0, smooth.Z)
                end
                Players.PlayerRemoving:Connect(function(p)
                    if p.Character then VeilState.velHistory[p.Character] = nil end
                end)
                local function Veil_HideFOV()
                    local V = VeilVisuals
                    local OFF = Vector2.new(-9999, -9999)
                    if V.FOVOuterRing then V.FOVOuterRing.Visible = false; V.FOVOuterRing.Position = OFF; V.FOVOuterRing.Radius = 0; V.FOVOuterRing.Transparency = 1 end
                    if V.FOVMainRing then V.FOVMainRing.Visible = false; V.FOVMainRing.Position = OFF; V.FOVMainRing.Radius = 0; V.FOVMainRing.Transparency = 1 end
                    if V.FOVInnerRing then V.FOVInnerRing.Visible = false; V.FOVInnerRing.Position = OFF; V.FOVInnerRing.Radius = 0; V.FOVInnerRing.Transparency = 1 end
                    if V.FOVCrossLines then for _, s in ipairs(V.FOVCrossLines) do s.Visible = false; s.From = OFF; s.To = OFF end end
                    if V.FOVTicks then for _, s in ipairs(V.FOVTicks) do s.Visible = false; s.From = OFF; s.To = OFF end end
                end
                local function Veil_HideTracker()
                    local V = VeilVisuals
                    local OFF = Vector2.new(-9999, -9999)
                    if V.TrackerOuterRing then V.TrackerOuterRing.Visible = false; V.TrackerOuterRing.Position = OFF; V.TrackerOuterRing.Radius = 0; V.TrackerOuterRing.Transparency = 1 end
                    if V.TrackerMainRing then V.TrackerMainRing.Visible = false; V.TrackerMainRing.Position = OFF; V.TrackerMainRing.Radius = 0; V.TrackerMainRing.Transparency = 1 end
                    if V.TrackerDotFill then V.TrackerDotFill.Visible = false; V.TrackerDotFill.Position = OFF; V.TrackerDotFill.Radius = 0 end
                    if V.TrackerDotOutline then V.TrackerDotOutline.Visible = false; V.TrackerDotOutline.Position = OFF; V.TrackerDotOutline.Radius = 0 end
                    if V.TrackerLine then V.TrackerLine.Visible = false; V.TrackerLine.From = OFF; V.TrackerLine.To = OFF end
                end
                local function Veil_HideAllVisuals() Veil_HideFOV(); Veil_HideTracker() end
                local function Veil_UpdateFOVVisuals(center)
                    local V = VeilVisuals
                    if not V.FOVOuterRing or not V.FOVMainRing or not V.FOVInnerRing then return end
                    if type(V.FOVCrossLines) ~= "table" or type(V.FOVTicks) ~= "table" then return end
                    local radius = math.max(10, tonumber(VD.VeilV2FOV) or 150)
                    local t = tick()
                    local pulse = (math.sin(t * 3) + 1) * 0.5
                    local slowPulse = (math.sin(t * 1.2) + 1) * 0.5
                    V.FOVOuterRing.Position = center; V.FOVOuterRing.Radius = radius + 2; V.FOVOuterRing.Transparency = 0.3 + pulse * 0.15; V.FOVOuterRing.Visible = true
                    V.FOVMainRing.Position = center; V.FOVMainRing.Radius = radius; V.FOVMainRing.Transparency = 0.7 + pulse * 0.25; V.FOVMainRing.Visible = true
                    V.FOVInnerRing.Position = center; V.FOVInnerRing.Radius = radius - 10; V.FOVInnerRing.Transparency = 0.25 + slowPulse * 0.2; V.FOVInnerRing.Visible = true
                    local gap, armLen = 4, 12
                    V.FOVCrossLines[1].From = Vector2.new(center.X, center.Y - gap); V.FOVCrossLines[1].To = Vector2.new(center.X, center.Y - gap - armLen); V.FOVCrossLines[1].Visible = true
                    V.FOVCrossLines[2].From = Vector2.new(center.X, center.Y + gap); V.FOVCrossLines[2].To = Vector2.new(center.X, center.Y + gap + armLen); V.FOVCrossLines[2].Visible = true
                    V.FOVCrossLines[3].From = Vector2.new(center.X - gap, center.Y); V.FOVCrossLines[3].To = Vector2.new(center.X - gap - armLen, center.Y); V.FOVCrossLines[3].Visible = true
                    V.FOVCrossLines[4].From = Vector2.new(center.X + gap, center.Y); V.FOVCrossLines[4].To = Vector2.new(center.X + gap + armLen, center.Y); V.FOVCrossLines[4].Visible = true
                    local tickLen = 9
                    for i = 1, 4 do
                        local angle = (i - 1) * math.pi / 2
                        local dirX, dirY = math.cos(angle), math.sin(angle)
                        V.FOVTicks[i].From = Vector2.new(center.X + dirX * radius, center.Y + dirY * radius)
                        V.FOVTicks[i].To = Vector2.new(center.X + dirX * (radius - tickLen), center.Y + dirY * (radius - tickLen))
                        V.FOVTicks[i].Visible = true
                    end
                end
                local function Veil_UpdateTrackerVisuals(targetScreenPos, dist)
                    local V = VeilVisuals
                    if not V.TrackerOuterRing or not V.TrackerMainRing or not V.TrackerDotFill or not V.TrackerDotOutline then return end
                    local t = tick()
                    local pulse = (math.sin(t * 4) + 1) * 0.5
                    local baseRadius = math.clamp(1000 / math.max(dist, 1), 20, 48)
                    V.TrackerOuterRing.Position = targetScreenPos; V.TrackerOuterRing.Radius = baseRadius + 3; V.TrackerOuterRing.Transparency = 0.25 + pulse * 0.15; V.TrackerOuterRing.Visible = true
                    V.TrackerMainRing.Position = targetScreenPos; V.TrackerMainRing.Radius = baseRadius; V.TrackerMainRing.Transparency = 0.75 + pulse * 0.2; V.TrackerMainRing.Visible = true
                    V.TrackerDotFill.Position = targetScreenPos; V.TrackerDotFill.Radius = 2.5 + pulse * 1.2; V.TrackerDotFill.Transparency = 0.85 + pulse * 0.15; V.TrackerDotFill.Visible = true
                    V.TrackerDotOutline.Position = targetScreenPos; V.TrackerDotOutline.Radius = 5 + pulse * 1.5; V.TrackerDotOutline.Transparency = 0.35; V.TrackerDotOutline.Visible = true
                end
                local function Veil_UpdateAimbot()
                    if GetRole() ~= "Killer" then
                        VeilState.target = nil; VeilState.lookVector = nil
                        Veil_HideAllVisuals(); return
                    end
                    local cam = Workspace.CurrentCamera
                    if not cam then return end
                    local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
                    -- The Show Veil FOV toggle controls visibility independently of aim activation.
                    if VD.VeilV2ShowFOV then pcall(Veil_UpdateFOVVisuals, center)
                    else pcall(Veil_HideFOV) end
                    if not VD.VeilV2Enabled then VeilState.target = nil; VeilState.lookVector = nil; pcall(Veil_HideTracker); return end
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local nearest, nearestPart = nil, nil
                    local bestDist = VD.VeilV2FOV or 150
                    local bestStudDist = VD.VeilV2MaxDist or 500
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and Veil_IsSurvivorVeil(p) and p.Character then
                            local pc = p.Character
                            local isDown = pc:GetAttribute("Knocked") == true or pc:GetAttribute("HookProgressDepleting") == true
                            if not isDown then
                                local hum = pc:FindFirstChildOfClass("Humanoid")
                                local targetPart = pc:FindFirstChild("UpperTorso") or pc:FindFirstChild("Torso") or pc:FindFirstChild("HumanoidRootPart")
                                if hum and hum.Health > 0 and targetPart then
                                    local sp, on = cam:WorldToViewportPoint(targetPart.Position)
                                    if on and sp.Z > 0 then
                                        local sd = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                        if sd < bestDist then
                                            local studDist = (targetPart.Position - hrp.Position).Magnitude
                                            if studDist <= bestStudDist then bestDist = sd; nearest = p; nearestPart = targetPart end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if nearest and nearest.Character and nearestPart then
                        local tp = nearestPart.Position
                        local hand = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
                        local origin = (hand and hand:IsA("BasePart")) and hand.Position or hrp.Position
                        local dir = tp - origin
                        local dist = dir.Magnitude
                        if dist > 0.1 and dist <= (VD.VeilV2MaxDist or 500) then
                            local isAuraActive = char:GetAttribute("special") == true
                            local prof
                            if isAuraActive then
                                prof = { v0 = VD.VeilV2AuraSpearSpeed or 165, g = VD.VeilV2AuraSpearGravity or 96.5, windup = 0.10, latency = 0.04, maxlead = 25, scale = VD.VeilV2LeadMultiplier or 1.4 }
                            else
                                prof = { v0 = VD.VeilV2SpearSpeed or 165, g = VD.VeilV2Gravity or 103, windup = 0.10, latency = 0.04, maxlead = 45, scale = VD.VeilV2LeadMultiplier or 1.4 }
                            end
                            local aimPoint = tp
                            if VD.VeilV2AutoPredict then
                                local vel = Veil_getCharacterVelocity(nearest.Character)
                                if vel.Magnitude > 0.5 then
                                    local h0 = Vector3.new(dir.X, 0, dir.Z)
                                    local _, tFlight = Veil_solvePitch(prof, h0.Magnitude, dir.Y)
                                    local ping = 0.08
                                    pcall(function() ping = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.35) end)
                                    local delay = tFlight + prof.windup + ping + prof.latency
                                    for _ = 1, 2 do
                                        local lead = vel * delay * prof.scale
                                        local maxLead = math.clamp(dist * 0.6, 3, prof.maxlead)
                                        if lead.Magnitude > maxLead then lead = lead.Unit * maxLead end
                                        aimPoint = tp + lead
                                        local ad = aimPoint - origin
                                        local ah = Vector3.new(ad.X, 0, ad.Z)
                                        local _, t2 = Veil_solvePitch(prof, math.max(ah.Magnitude, 0.1), ad.Y)
                                        delay = t2 + prof.windup + ping + prof.latency
                                    end
                                end
                            end
                            local adir = aimPoint - origin
                            local ah = Vector3.new(adir.X, 0, adir.Z)
                            local ahDist = ah.Magnitude
                            local pitch = Veil_solvePitch(prof, ahDist, adir.Y)
                            if ahDist > 0.001 then VeilState.lookVector = ah.Unit * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)
                            else VeilState.lookVector = adir.Unit end
                            VeilState.target = nearest
                            if VD.VeilV2ShowTracker then
                                local sp, vis = cam:WorldToViewportPoint(tp)
                                if vis and sp.Z > 0 then
                                    local screenDist = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                    if screenDist <= (VD.VeilV2FOV or 150) + 100 then
                                        pcall(Veil_UpdateTrackerVisuals, Vector2.new(sp.X, sp.Y), dist)
                                        local bottomCenter = Vector2.new(center.X, cam.ViewportSize.Y)
                                        local V = VeilVisuals
                                        if V.TrackerLine then pcall(function() V.TrackerLine.From = bottomCenter; V.TrackerLine.To = Vector2.new(sp.X, sp.Y); V.TrackerLine.Visible = true end) end
                                    else pcall(Veil_HideTracker) end
                                end
                            else pcall(Veil_HideTracker) end
                        end
                    else VeilState.target = nil; VeilState.lookVector = nil; pcall(Veil_HideTracker) end
                end

            local function VeilV2_IsSpearthrowRemote(candidate)
                if typeof(candidate) ~= "Instance" then return false end
                local ok, isRemote = pcall(function() return candidate:IsA("RemoteEvent") end)
                if not ok or not isRemote or candidate.Name ~= "Spearthrow" then return false end
                local remotes = ReplicatedStorage:FindFirstChild("Remotes")
                local killers = remotes and remotes:FindFirstChild("Killers")
                local veil = killers and killers:FindFirstChild("Veil")
                local spearRemote = veil and veil:FindFirstChild("Spearthrow")
                return spearRemote ~= nil and candidate == spearRemote
            end

            local function VeilV2_setupInterceptor()
                if VeilV2HookState.remoteHooked then return end
                if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then return end
                task.spawn(function()
                    local success = pcall(function()
                        local oldNamecall
                        local wrap = type(newcclosure) == "function" and newcclosure or function(fn) return fn end
                        oldNamecall = hookmetamethod(game, "__namecall", wrap(function(self, ...)
                            local method = getnamecallmethod()
                            local ownCall = false
                            if type(checkcaller) == "function" then
                                pcall(function() ownCall = checkcaller() == true end)
                            end
                            if not ownCall and method == "FireServer" and VD.VeilV2Enabled
                                and typeof(VeilState.lookVector) == "Vector3" and GetRole() == "Killer"
                                and VeilV2_IsSpearthrowRemote(self) then
                                local args = {...}
                                local argCount = select("#", ...)
                                -- Spearthrow signature: (direction, speed, startPosition, ...).
                                if typeof(args[1]) == "Vector3" then
                                    args[1] = VeilState.lookVector
                                    return oldNamecall(self, unpack(args, 1, argCount))
                                end
                            end
                            return oldNamecall(self, ...)
                        end))
                        if type(oldNamecall) ~= "function" then error("hookmetamethod did not return original namecall") end
                    end)
                    VeilV2HookState.remoteHooked = success
                end)
            end

            VeilV2_setupInterceptor()
            VeilV2Connection = RunService.RenderStepped:Connect(function()
                if not VeilV2Connection then return end
                pcall(Veil_UpdateAimbot)
            end)

            W.MAWWW_VeilV2_API = {
                setEnabled = function(v)
                    VD.VeilV2Enabled = v == true
                    if VD.VeilV2Enabled then
                        VeilV2_setupInterceptor()
                    else
                        pcall(Veil_HideAllVisuals)
                        VeilState.target = nil
                        VeilState.lookVector = nil
                    end
                end,
                setFOV = function(v) VD.VeilV2FOV = tonumber(v) or VD.VeilV2FOV end,
                setMaxDistance = function(v) VD.VeilV2MaxDist = tonumber(v) or VD.VeilV2MaxDist end,
                setSpeed = function(v) VD.VeilV2SpearSpeed = tonumber(v) or VD.VeilV2SpearSpeed end,
                setGravity = function(v) VD.VeilV2Gravity = tonumber(v) or VD.VeilV2Gravity end,
                setAuraSpeed = function(v) VD.VeilV2AuraSpearSpeed = tonumber(v) or VD.VeilV2AuraSpearSpeed end,
                setAuraGravity = function(v) VD.VeilV2AuraSpearGravity = tonumber(v) or VD.VeilV2AuraSpearGravity end,
                setLead = function(v) VD.VeilV2LeadMultiplier = tonumber(v) or VD.VeilV2LeadMultiplier end,
                setAutoPredict = function(v) VD.VeilV2AutoPredict = v == true end,
                setTracker = function(v) VD.VeilV2ShowTracker = v == true end,
                setShowFOV = function(v) VD.VeilV2ShowFOV = v == true end,
            }
        end

        -- Silent Veil V3 + Silent Pistol V3: full engine port from the supplied DeepSeek combined source.
        -- The standalone source UI is intentionally omitted; controls are wired into Mawww Hub's existing WindUI.
        do
            local W3 = getgenv()
            local Players3 = game:GetService("Players")
            local RunService3 = game:GetService("RunService")
            local ReplicatedStorage3 = game:GetService("ReplicatedStorage")
            local Stats3 = game:GetService("Stats")
            local LocalPlayer3 = Players3.LocalPlayer
            local workspace3 = workspace

            local initialSettings = {
                Veil_Enabled = VD.VeilV3EngineEnabled == true,
                Veil_FOV = tonumber(VD.VeilV3FOV) or 150,
                Veil_MaxDist = tonumber(VD.VeilV3MaxDist) or 500,
                Veil_Speed = tonumber(VD.VeilV3SpearSpeed) or 165,
                Veil_Gravity = tonumber(VD.VeilV3Gravity) or 103,
                Veil_AuraSpeed = tonumber(VD.VeilV3AuraSpearSpeed) or 165,
                Veil_AuraGravity = tonumber(VD.VeilV3AuraSpearGravity) or 96.5,
                Veil_AutoPredict = VD.VeilV3AutoPredict ~= false,
                Veil_LeadMult = tonumber(VD.VeilV3LeadMultiplier) or 1.4,
                Veil_PingLead = 1.0,
                Veil_AntiStrafing = true,
                Veil_ShowFOV = VD.VeilV3ShowFOV ~= false,
                Veil_ShowLaser = true,
                Veil_ShowTracker = VD.VeilV3ShowTracker ~= false,

                ToF_Enabled = VD.SilentPistolV3Enabled == true,
                ToF_FOV = tonumber(VD.TOFV3_FOV) or 150,
                ToF_MaxDist = tonumber(VD.TOFV3_MaxDist) or 300,
                ToF_TargetMode = VD.TOFV3_TargetMode or "Killer",
                ToF_ShowFOV = VD.TOFV3_ShowFOV ~= false,
                ToF_ShowLaser = VD.TOFV3_ShowLaser ~= false,
                ToF_WallCheck = VD.TOFV3_WallCheck == true,
                ToF_BlockWhenKnocked = VD.TOFV3_BlockKnocked ~= false,
                ToF_AutoPredict = VD.TOFV3_AutoPredict ~= false,
                ToF_PingLead = tonumber(VD.TOFV3_PingLead) or 1.0,
            }

            local existingEngine = W3.MAWWW_CombinedV3Engine
            if existingEngine and existingEngine.Active and existingEngine.Settings then
                for key, value in pairs(initialSettings) do
                    existingEngine.Settings[key] = value
                end
                W3.MAWWW_VeilV3_API = existingEngine.VeilAPI
                W3.MAWWW_PistolV3_API = existingEngine.PistolAPI
            else
                local Settings3 = initialSettings
                local State3 = {
                    veilVelocity = {},
                    tofVelocity = {},
                    scpCache = {},
                    scpCacheT = 0,
                    veilFiring = false,
                    connections = {},
                    hookActive = false,
                    oldNamecall = nil,
                    veilLaser = nil,
                    tofLaser = nil,
                    drawings = {},
                }
                local cachedToF3, cachedSpear3 = nil, nil

                local function isAlive3(char)
                    if not char or not char.Parent then return false end
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    return hum ~= nil and hum.Health > 0 and char:GetAttribute("State") ~= "Dead"
                end

                local function isDowned3(char)
                    if not char then return false end
                    return char:GetAttribute("Knocked") == true
                        or char:GetAttribute("IsHooked") == true
                        or char:GetAttribute("IsCarried") == true
                end

                local function getRole3(player)
                    if not player or not player.Team then return "Unknown" end
                    if player.Team.Name == "Killer" then return "Killer" end
                    if player.Team.Name == "Survivors" then return "Survivor" end
                    return "Spectator"
                end

                local function getPing3()
                    local ok, value = pcall(function()
                        return Stats3.Network.ServerStatsItem["Data Ping"]:GetValue()
                    end)
                    if ok and value then
                        return math.clamp((tonumber(value) or 0) / 1000, 0, 0.5)
                    end
                    return 0
                end

                local function trackVelocity3(store, char, pos)
                    if not char then return Vector3.zero, 1 end
                    local now = tick()
                    local data = store[char]
                    if not data then
                        store[char] = {pos = pos, t = now, vel = Vector3.zero, velSmooth = Vector3.zero, turn = 0}
                        return Vector3.zero, 1
                    end
                    local dt = now - data.t
                    if dt > 0.001 then
                        local rawVel = (pos - data.pos) / dt
                        rawVel = Vector3.new(rawVel.X, 0, rawVel.Z)
                        local root = char:FindFirstChild("HumanoidRootPart")
                        if root then
                            local rootVel = root.AssemblyLinearVelocity
                            local flat = Vector3.new(rootVel.X, 0, rootVel.Z)
                            if flat.Magnitude > 0.5 and flat.Magnitude < 100 then rawVel = flat end
                        end
                        data.vel = data.vel:Lerp(rawVel, 0.4)
                        data.velSmooth = data.velSmooth:Lerp(data.vel, 0.3)
                        if data.vel.Magnitude > 2 and rawVel.Magnitude > 2 then
                            local dot = data.vel:Dot(rawVel) / (data.vel.Magnitude * rawVel.Magnitude)
                            local turnAmount = math.clamp(1 - dot, 0, 1)
                            data.turn = data.turn * 0.7 + turnAmount * 0.3
                        end
                        data.pos = pos
                        data.t = now
                    end
                    local leadFactor = 1.0
                    if Settings3.Veil_AntiStrafing then
                        leadFactor = 0.55 + 0.45 * math.clamp(1 - data.turn, 0, 1)
                    end
                    return data.velSmooth, leadFactor
                end

                local function getSCPs3()
                    if tick() - State3.scpCacheT < 0.5 then return State3.scpCache end
                    State3.scpCacheT = tick()
                    local list = {}
                    local map = workspace3:FindFirstChild("Map")
                    if map then
                        for _, obj in ipairs(map:GetDescendants()) do
                            if obj:IsA("Model") and obj ~= LocalPlayer3.Character then
                                local attrs = obj:GetAttributes()
                                if obj:GetAttribute("CorpseCreated0492") or next(attrs) ~= nil then
                                    local root = obj:FindFirstChild("HumanoidRootPart")
                                    if root then table.insert(list, {model = obj, root = root}) end
                                end
                            end
                        end
                    end
                    State3.scpCache = list
                    return list
                end

                local function selectTarget3(filterFn, fovRadius, maxDist)
                    local char = LocalPlayer3.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local camera = workspace3.CurrentCamera
                    if not hrp or not camera then return nil end
                    local viewport = camera.ViewportSize
                    local center = Vector2.new(viewport.X / 2, viewport.Y / 2)
                    local best, bestDist = nil, math.max(1, tonumber(fovRadius) or 150)
                    for _, player in ipairs(Players3:GetPlayers()) do
                        if player ~= LocalPlayer3 and player.Character and filterFn(player) then
                            if isAlive3(player.Character) and not isDowned3(player.Character) then
                                local part = player.Character:FindFirstChild("UpperTorso")
                                    or player.Character:FindFirstChild("Torso")
                                    or player.Character:FindFirstChild("HumanoidRootPart")
                                if part and part:IsA("BasePart") then
                                    local distance3 = (part.Position - hrp.Position).Magnitude
                                    if distance3 <= (tonumber(maxDist) or 300) then
                                        local screen, onScreen = camera:WorldToViewportPoint(part.Position)
                                        if onScreen and screen.Z > 0 then
                                            local distance2 = (Vector2.new(screen.X, screen.Y) - center).Magnitude
                                            if distance2 < bestDist then
                                                bestDist = distance2
                                                best = part
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    return best
                end

                local function getVeilTarget3()
                    return selectTarget3(function(player) return getRole3(player) == "Survivor" end,
                        Settings3.Veil_FOV, Settings3.Veil_MaxDist)
                end

                local function getToFTarget3()
                    local mode = Settings3.ToF_TargetMode
                    if mode == "Zombie" then
                        local char = LocalPlayer3.Character
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        local camera = workspace3.CurrentCamera
                        if not hrp or not camera then return nil end
                        local vp = camera.ViewportSize
                        local center = Vector2.new(vp.X / 2, vp.Y / 2)
                        local best, bestDist = nil, Settings3.ToF_FOV
                        for _, scp in ipairs(getSCPs3()) do
                            if scp.model and scp.model.Parent and scp.root and scp.root.Parent then
                                local dist = (scp.root.Position - hrp.Position).Magnitude
                                if dist <= Settings3.ToF_MaxDist then
                                    local screen, onScreen = camera:WorldToViewportPoint(scp.root.Position)
                                    if onScreen and screen.Z > 0 then
                                        local dist2 = (Vector2.new(screen.X, screen.Y) - center).Magnitude
                                        if dist2 < bestDist then bestDist = dist2; best = scp.root end
                                    end
                                end
                            end
                        end
                        return best
                    end
                    local targetRole = mode == "Survivors" and "Survivor" or mode
                    return selectTarget3(function(player) return getRole3(player) == targetRole end,
                        Settings3.ToF_FOV, Settings3.ToF_MaxDist)
                end

                local function solveTrajectory3(startPos, targetPos, speed, gravity)
                    local delta = targetPos - startPos
                    local flat = Vector3.new(delta.X, 0, delta.Z)
                    local dist = flat.Magnitude
                    if dist < 0.1 then return nil, nil end
                    local speedSafe = math.max(1, tonumber(speed) or 165)
                    local gravitySafe = math.max(1, tonumber(gravity) or 103)
                    local minAng, maxAng, angle = math.rad(-55), math.rad(55), 0
                    for _ = 1, 20 do
                        angle = (minAng + maxAng) / 2
                        local vx = speedSafe * math.cos(angle)
                        local vy = speedSafe * math.sin(angle)
                        if vx < 0.1 then minAng = angle else
                            local flightTime = dist / vx
                            local y = vy * flightTime - 0.5 * gravitySafe * flightTime * flightTime
                            if y < delta.Y then minAng = angle else maxAng = angle end
                            if math.abs(y - delta.Y) < 0.05 then break end
                        end
                    end
                    local vx = speedSafe * math.cos(angle)
                    local vy = speedSafe * math.sin(angle)
                    if vx < 0.1 then return nil, nil end
                    local direction = flat.Unit * vx + Vector3.new(0, vy, 0)
                    if direction.Magnitude < 0.001 then return nil, nil end
                    return direction.Unit, dist / vx
                end

                local function calculateSpearDirection3(originalDir, speed, originPos)
                    local targetPart = getVeilTarget3()
                    if not targetPart or not targetPart.Parent then return nil end
                    local character = LocalPlayer3.Character
                    if not character then return nil end
                    local targetChar = targetPart.Parent
                    local targetPos = targetPart.Position
                    local useSpeed = tonumber(speed) or Settings3.Veil_Speed
                    local isSpecial = character:GetAttribute("special") == true
                    local useGravity = isSpecial and (tonumber(Settings3.Veil_AuraGravity) or 96.5) or (tonumber(Settings3.Veil_Gravity) or 103)
                    if Settings3.Veil_AutoPredict then
                        useSpeed = isSpecial and (tonumber(Settings3.Veil_AuraSpeed) or 165) or 142.5
                    end
                    if typeof(originPos) ~= "Vector3" then
                        local hrp = character:FindFirstChild("HumanoidRootPart")
                        originPos = hrp and hrp.Position or nil
                    end
                    if not originPos then return nil end
                    local targetVel, leadFactor = Vector3.zero, 1
                    if Settings3.Veil_AutoPredict then
                        targetVel, leadFactor = trackVelocity3(State3.veilVelocity, targetChar, targetPos)
                    end
                    local pingLead = getPing3() * Settings3.Veil_PingLead
                    local initialTime = (targetPos - originPos).Magnitude / math.max(useSpeed, 1)
                    local predictedPos = targetPos + targetVel * ((initialTime + pingLead) * Settings3.Veil_LeadMult * leadFactor)
                    local newTime = (predictedPos - originPos).Magnitude / math.max(useSpeed, 1)
                    predictedPos = targetPos + targetVel * ((newTime + pingLead) * Settings3.Veil_LeadMult * leadFactor)
                    local direction = solveTrajectory3(originPos, predictedPos, useSpeed, useGravity)
                    if direction then return direction, useSpeed end
                    local fallback = predictedPos - originPos
                    if fallback.Magnitude > 0.1 then return fallback.Unit, useSpeed end
                    return nil
                end

                local function getToFRemote3()
                    local remotes = ReplicatedStorage3:FindFirstChild("Remotes")
                    local items = remotes and remotes:FindFirstChild("Items")
                    local tof = items and items:FindFirstChild("Twist of Fate")
                    local fire = tof and tof:FindFirstChild("Fire")
                    if fire and fire:IsA("RemoteEvent") then return fire end
                    return nil
                end

                local function getSpearRemote3()
                    local remotes = ReplicatedStorage3:FindFirstChild("Remotes")
                    local killers = remotes and remotes:FindFirstChild("Killers")
                    local veil = killers and killers:FindFirstChild("Veil")
                    local spear = veil and veil:FindFirstChild("Spearthrow")
                    if spear and spear:IsA("RemoteEvent") then return spear end
                    return nil
                end

                local function getGunOrigin3(gunObj)
                    if not gunObj or typeof(gunObj) ~= "Instance" then return nil end
                    if gunObj:IsA("BasePart") then return gunObj.Position end
                    local part = gunObj:FindFirstChildWhichIsA("BasePart", true)
                    return part and part.Position or nil
                end

                local function calculateToFDirection3(originPos)
                    local targetPart = getToFTarget3()
                    if not targetPart or not targetPart.Parent then return nil end
                    local targetPos = targetPart.Position
                    local targetChar = targetPart.Parent
                    local targetVel = Vector3.zero
                    if Settings3.ToF_AutoPredict then
                        targetVel = select(1, trackVelocity3(State3.tofVelocity, targetChar, targetPos))
                    end
                    local bulletSpeed = 400
                    local pingLead = getPing3() * Settings3.ToF_PingLead
                    local travelTime = (targetPos - originPos).Magnitude / bulletSpeed
                    local predictedPos = targetPos + targetVel * (travelTime + pingLead)
                    travelTime = (predictedPos - originPos).Magnitude / bulletSpeed
                    predictedPos = targetPos + targetVel * (travelTime + pingLead)
                    local direction = predictedPos - originPos
                    if direction.Magnitude < 0.1 then return nil end
                    return direction.Unit
                end

                local function hasClearTarget3()
                    local character = LocalPlayer3.Character
                    local hrp = character and character:FindFirstChild("HumanoidRootPart")
                    if not hrp then return false end
                    local origin = hrp.Position + Vector3.new(0, 1.5, 0)
                    local mode = Settings3.ToF_TargetMode
                    local targets = {}
                    if mode == "Zombie" then
                        for _, scp in ipairs(getSCPs3()) do
                            if scp.root and scp.root.Parent then table.insert(targets, scp.root) end
                        end
                    else
                        local targetRole = mode == "Survivors" and "Survivor" or mode
                        for _, player in ipairs(Players3:GetPlayers()) do
                            if player ~= LocalPlayer3 and player.Character and getRole3(player) == targetRole and isAlive3(player.Character) then
                                local part = player.Character:FindFirstChild("UpperTorso") or player.Character:FindFirstChild("Torso") or player.Character:FindFirstChild("HumanoidRootPart")
                                if part then table.insert(targets, part) end
                            end
                        end
                    end
                    for _, targetPart in ipairs(targets) do
                        local params = RaycastParams.new()
                        params.FilterType = Enum.RaycastFilterType.Exclude
                        params.FilterDescendantsInstances = {character, targetPart.Parent}
                        local hit = workspace3:Raycast(origin, targetPart.Position - origin, params)
                        if not hit then return true end
                    end
                    return false
                end

                local function handler3(self, ...)
                    local args = table.pack(...)
                    local count = args.n
                    if cachedToF3 and rawequal(self, cachedToF3) and Settings3.ToF_Enabled then
                        if count >= 2 and typeof(args[2]) == "Vector3" then
                            if Settings3.ToF_WallCheck and W3.MAWWW_ToFV3_WallBlocked == true then return {Block = true} end
                            if Settings3.ToF_BlockWhenKnocked then
                                local character = LocalPlayer3.Character
                                if character and isDowned3(character) then return {Block = true} end
                            end
                            local origin = getGunOrigin3(args[1])
                            if not origin then
                                local character = LocalPlayer3.Character
                                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                                if hrp then origin = hrp.Position + Vector3.new(0, 1.5, 0) end
                            end
                            if origin then
                                local direction = calculateToFDirection3(origin)
                                if direction then args[2] = direction; return {Args = args, N = count} end
                            end
                        end
                        return nil
                    end
                    if cachedSpear3 and rawequal(self, cachedSpear3) and Settings3.Veil_Enabled then
                        if State3.veilFiring then return nil end
                        if count >= 3 and typeof(args[1]) == "Vector3" and typeof(args[3]) == "Vector3" then
                            State3.veilFiring = true
                            local ok, direction, newSpeed = pcall(function()
                                local newDir, speedValue = calculateSpearDirection3(args[1], tonumber(args[2]) or Settings3.Veil_Speed, args[3])
                                return newDir, speedValue
                            end)
                            State3.veilFiring = false
                            if ok and direction then
                                args[1] = direction
                                if newSpeed then args[2] = newSpeed end
                                return {Args = args, N = count}
                            end
                        end
                        return nil
                    end
                    return nil
                end

                local function installHook3()
                    if State3.hookActive and State3.oldNamecall then return true end
                    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
                        warn("[Mawww Hub] Silent V3 requires hookmetamethod/getnamecallmethod")
                        return false
                    end
                    local wrapper = type(newcclosure) == "function" and newcclosure or function(fn) return fn end
                    local ok, previous = pcall(function()
                        return hookmetamethod(game, "__namecall", wrapper(function(self, ...)
                            local old = State3.oldNamecall
                            if type(old) ~= "function" then return end
                            if type(checkcaller) == "function" and checkcaller() then return old(self, ...) end
                            local method = getnamecallmethod()
                            if method ~= "FireServer" and method ~= "fireServer" then return old(self, ...) end
                            local handled, result = pcall(handler3, self, ...)
                            if handled and result then
                                if result.Block then return nil end
                                if result.Args then return old(self, table.unpack(result.Args, 1, result.N or result.Args.n)) end
                            end
                            return old(self, ...)
                        end))
                    end)
                    if not ok or type(previous) ~= "function" then
                        warn("[Mawww Hub] Silent V3 remote hook could not be installed")
                        return false
                    end
                    State3.oldNamecall = previous
                    State3.hookActive = true
                    return true
                end

                local function ensureLaser3(which)
                    local field = which == "tof" and "tofLaser" or "veilLaser"
                    local laser = State3[field]
                    if laser and laser.Parent then return laser end
                    local ok, part = pcall(function()
                        local p = Instance.new("Part")
                        p.Name = which == "tof" and "VD_ToFLaserV3" or "VD_VeilLaserV3"
                        p.Anchored = true
                        p.CanCollide = false
                        p.CanTouch = false
                        p.CanQuery = false
                        p.CastShadow = false
                        p.Material = Enum.Material.Neon
                        p.Color = which == "tof" and Color3.fromRGB(100, 200, 255) or Color3.fromRGB(255, 80, 80)
                        p.Size = Vector3.new(0.05, 0.05, 1)
                        p.Transparency = 1
                        p.Parent = workspace3
                        return p
                    end)
                    if ok then State3[field] = part end
                    return ok and part or nil
                end

                local fovGui3, fovVeil3, fovTof3
                local function ensureFovGui3()
                    if fovGui3 and fovGui3.Parent then return end
                    local playerGui = LocalPlayer3:FindFirstChildOfClass("PlayerGui") or LocalPlayer3:FindFirstChild("PlayerGui")
                    if not playerGui then return end
                    local old = playerGui:FindFirstChild("MAWWW_SilentAimV3_FOV")
                    if old then pcall(function() old:Destroy() end) end
                    fovGui3 = Instance.new("ScreenGui")
                    fovGui3.Name = "MAWWW_SilentAimV3_FOV"
                    fovGui3.ResetOnSpawn = false
                    fovGui3.IgnoreGuiInset = true
                    fovGui3.DisplayOrder = 100
                    fovGui3.Parent = playerGui
                    local function makeCircle(color, name)
                        local frame = Instance.new("Frame")
                        frame.Name = name
                        frame.AnchorPoint = Vector2.new(0.5, 0.5)
                        frame.Position = UDim2.new(0.5, 0, 0.5, 0)
                        frame.Size = UDim2.fromOffset(300, 300)
                        frame.BackgroundTransparency = 1
                        frame.Visible = false
                        frame.Parent = fovGui3
                        Instance.new("UICorner", frame).CornerRadius = UDim.new(1, 0)
                        local stroke = Instance.new("UIStroke")
                        stroke.Color = color
                        stroke.Thickness = 1.5
                        stroke.Transparency = 0.2
                        stroke.Parent = frame
                        return frame
                    end
                    fovVeil3 = makeCircle(Color3.fromRGB(255, 100, 100), "VeilFOV")
                    fovTof3 = makeCircle(Color3.fromRGB(100, 200, 255), "ToFFOV")
                end

                local function ensureDrawings3()
                    if typeof(Drawing) ~= "table" or type(Drawing.new) ~= "function" then return end
                    local function create(kind, key, color, radius)
                        if State3.drawings[key] then return end
                        pcall(function()
                            local item = Drawing.new(kind)
                            item.Color = color
                            item.Thickness = kind == "Circle" and 2 or 1.5
                            item.Transparency = 0.85
                            if kind == "Circle" then item.Filled = false; item.NumSides = 32 end
                            if radius then item.Radius = radius end
                            item.Visible = false
                            State3.drawings[key] = item
                        end)
                    end
                    create("Circle", "VeilTracker", Color3.fromRGB(255, 100, 100), 7)
                    create("Line", "VeilTrackerLine", Color3.fromRGB(255, 100, 100))
                    create("Circle", "ToFTracker", Color3.fromRGB(100, 200, 255), 7)
                    create("Line", "ToFTrackerLine", Color3.fromRGB(100, 200, 255))
                end

                local function hideDrawing3(key)
                    local item = State3.drawings[key]
                    if item then pcall(function() item.Visible = false end) end
                end

                local function updateDrawingTarget3(prefix, targetPart, enabled, camera)
                    local circle = State3.drawings[prefix .. "Tracker"]
                    local line = State3.drawings[prefix .. "TrackerLine"]
                    if not enabled or not targetPart or not targetPart.Parent or not camera then
                        hideDrawing3(prefix .. "Tracker")
                        hideDrawing3(prefix .. "TrackerLine")
                        return
                    end
                    local screen, onScreen = camera:WorldToViewportPoint(targetPart.Position)
                    if not onScreen or screen.Z <= 0 then
                        hideDrawing3(prefix .. "Tracker")
                        hideDrawing3(prefix .. "TrackerLine")
                        return
                    end
                    local pos = Vector2.new(screen.X, screen.Y)
                    if circle then circle.Position = pos; circle.Radius = 7; circle.Visible = true end
                    if line then
                        line.From = Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y)
                        line.To = pos
                        line.Visible = true
                    end
                end

                local function getToFVisualOrigin3()
                    local char = LocalPlayer3.Character
                    local tool = char and char:FindFirstChild("Twist of Fate", true)
                    local origin = getGunOrigin3(tool)
                    if origin then return origin end
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    return hrp and (hrp.Position + Vector3.new(0, 1.5, 0)) or nil
                end

                local function setLaser3(laser, origin, targetPart, enabled)
                    if not laser or not laser.Parent then return end
                    if not enabled or not origin or not targetPart or not targetPart.Parent then
                        laser.Transparency = 1
                        return
                    end
                    local targetPos = targetPart.Position
                    local distance = (targetPos - origin).Magnitude
                    if distance <= 0.1 then laser.Transparency = 1; return end
                    laser.Size = Vector3.new(0.05, 0.05, distance)
                    laser.CFrame = CFrame.new((origin + targetPos) / 2, targetPos)
                    laser.Transparency = 0.2
                end

                local function computeWallBlocked3()
                    return not hasClearTarget3()
                end

                local heartbeat3 = RunService3.Heartbeat:Connect(function()
                    if not cachedToF3 or not cachedToF3.Parent then cachedToF3 = getToFRemote3() end
                    if not cachedSpear3 or not cachedSpear3.Parent then cachedSpear3 = getSpearRemote3() end
                    if Settings3.ToF_Enabled and Settings3.ToF_WallCheck then
                        W3.MAWWW_ToFV3_WallBlocked = computeWallBlocked3()
                    else
                        W3.MAWWW_ToFV3_WallBlocked = false
                    end
                end)
                table.insert(State3.connections, heartbeat3)

                local render3 = RunService3.RenderStepped:Connect(function()
                    ensureFovGui3()
                    ensureDrawings3()
                    local camera = workspace3.CurrentCamera
                    if fovVeil3 then
                        fovVeil3.Size = UDim2.fromOffset(Settings3.Veil_FOV * 2, Settings3.Veil_FOV * 2)
                        fovVeil3.Visible = Settings3.Veil_Enabled and Settings3.Veil_ShowFOV
                    end
                    if fovTof3 then
                        fovTof3.Size = UDim2.fromOffset(Settings3.ToF_FOV * 2, Settings3.ToF_FOV * 2)
                        fovTof3.Visible = Settings3.ToF_Enabled and Settings3.ToF_ShowFOV
                    end

                    local veilTarget = (Settings3.Veil_Enabled and getRole3(LocalPlayer3) == "Killer") and getVeilTarget3() or nil
                    local veilOrigin = nil
                    local character = LocalPlayer3.Character
                    local hrp = character and character:FindFirstChild("HumanoidRootPart")
                    if hrp then veilOrigin = hrp.Position + Vector3.new(0, 1.5, 0) end
                    local veilLaser = ensureLaser3("veil")
                    setLaser3(veilLaser, veilOrigin, veilTarget, Settings3.Veil_Enabled and Settings3.Veil_ShowLaser)
                    updateDrawingTarget3("Veil", veilTarget, Settings3.Veil_Enabled and Settings3.Veil_ShowTracker, camera)

                    local tofTarget = Settings3.ToF_Enabled and getToFTarget3() or nil
                    local tofLaser = ensureLaser3("tof")
                    setLaser3(tofLaser, getToFVisualOrigin3(), tofTarget, Settings3.ToF_Enabled and Settings3.ToF_ShowLaser)
                    updateDrawingTarget3("ToF", tofTarget, Settings3.ToF_Enabled and Settings3.ToF_ShowLaser, camera)
                end)
                table.insert(State3.connections, render3)

                local function hideVisuals3()
                    if fovVeil3 then fovVeil3.Visible = false end
                    if fovTof3 then fovTof3.Visible = false end
                    if State3.veilLaser then State3.veilLaser.Transparency = 1 end
                    if State3.tofLaser then State3.tofLaser.Transparency = 1 end
                    for key in pairs(State3.drawings) do hideDrawing3(key) end
                end

                local function disableOtherVeil3()
                    VD.VeilEnabled = false
                    VD.VeilV2Enabled = false
                    if W3.MAWWW_VeilV1_API and type(W3.MAWWW_VeilV1_API.setEnabled) == "function" then
                        pcall(function() W3.MAWWW_VeilV1_API.setEnabled(false) end)
                    end
                    if W3.MAWWW_VeilV2_API and type(W3.MAWWW_VeilV2_API.setEnabled) == "function" then
                        pcall(function() W3.MAWWW_VeilV2_API.setEnabled(false) end)
                    end
                end
                local function disableOtherPistol3()
                    VD.TOFV1_SilentAim = false
                    VD.SilentPistolV2Enabled = false
                    if type(W3.SetToFSilentAimV1) == "function" then pcall(function() W3.SetToFSilentAimV1(false) end) end
                    if type(W3.SetPistolV2Enabled) == "function" then pcall(function() W3.SetPistolV2Enabled(false) end) end
                end

                local VeilAPI3 = {
                    setEnabled = function(value)
                        Settings3.Veil_Enabled = value == true
                        VD.VeilV3EngineEnabled = Settings3.Veil_Enabled
                        VD.VeilV3Enabled = false
                        if Settings3.Veil_Enabled then disableOtherVeil3() else hideVisuals3() end
                    end,
                    setAutoPredict = function(value) Settings3.Veil_AutoPredict = value == true; VD.VeilV3AutoPredict = Settings3.Veil_AutoPredict end,
