                    setAuraSpeed = function(value) Settings3.Veil_AuraSpeed = tonumber(value) or Settings3.Veil_AuraSpeed; VD.VeilV3AuraSpearSpeed = Settings3.Veil_AuraSpeed end,
                    setAuraGravity = function(value) Settings3.Veil_AuraGravity = tonumber(value) or Settings3.Veil_AuraGravity; VD.VeilV3AuraSpearGravity = Settings3.Veil_AuraGravity end,
                    setTracker = function(value) Settings3.Veil_ShowTracker = value == true; VD.VeilV3ShowTracker = Settings3.Veil_ShowTracker end,
