                    setFOV = function(value) Settings3.Veil_FOV = tonumber(value) or Settings3.Veil_FOV; VD.VeilV3FOV = Settings3.Veil_FOV end,
                    setMaxDistance = function(value) Settings3.Veil_MaxDist = tonumber(value) or Settings3.Veil_MaxDist; VD.VeilV3MaxDist = Settings3.Veil_MaxDist end,
