                    setWallCheck = function(value) Settings3.ToF_WallCheck = value == true; VD.TOFV3_WallCheck = Settings3.ToF_WallCheck end,
                    setBlockKnocked = function(value) Settings3.ToF_BlockWhenKnocked = value == true; VD.TOFV3_BlockKnocked = Settings3.ToF_BlockWhenKnocked end,
                    setAutoPredict = function(value) Settings3.ToF_AutoPredict = value == true; VD.TOFV3_AutoPredict = Settings3.ToF_AutoPredict end,
                    setFOV = function(value) Settings3.ToF_FOV = tonumber(value) or Settings3.ToF_FOV; VD.TOFV3_FOV = Settings3.ToF_FOV end,
                    setMaxDistance = function(value) Settings3.ToF_MaxDist = tonumber(value) or Settings3.ToF_MaxDist; VD.TOFV3_MaxDist = Settings3.ToF_MaxDist end,
                    setPingLead = function(value) Settings3.ToF_PingLead = tonumber(value) or Settings3.ToF_PingLead; VD.TOFV3_PingLead = Settings3.ToF_PingLead end,
