                    Settings = Settings3,
                    State = State3,
                    VeilAPI = VeilAPI3,
                    PistolAPI = PistolAPI3,
                    Cleanup = function()
                        -- Leave the shared namecall chain intact; simply disable this engine and destroy its owned visuals.
                        Settings3.Veil_Enabled = false
                        Settings3.ToF_Enabled = false
                        for _, connection in ipairs(State3.connections) do pcall(function() connection:Disconnect() end) end
                        State3.connections = {}
