            ToF1State.TargetGui = gui
        end
        local function ToF1_StartConn()
            if ToF1State.Connection then return end
            ToF1State.Connection = RunService.Heartbeat:Connect(function()
                if ToF1_IsBlocked() then ToF1State.IsAiming = false; if ToF1State.TouchInput then ToF1State.TouchInput = nil end; if ToF1State.LaserBeam then ToF1State.LaserBeam.Transparency = 1 end; return end
                if not VD.TOFV1_SilentAim or not ToF1State.IsAiming then if ToF1State.LaserBeam then ToF1State.LaserBeam.Transparency = 1 end; return end
                local _, _, op, tp = ToF1_GetTarget()
                if op and tp then
                    pcall(function()
                        local c = LocalPlayer.Character
                        local hrp = c and c:FindFirstChild("HumanoidRootPart")
                        if hrp and not c:GetAttribute("IsCarried") then hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z)) end
                        if VD.TOFV1_LockAim and Workspace.CurrentCamera then
                            local cam = Workspace.CurrentCamera
                            local wanted = CFrame.lookAt(cam.CFrame.Position, tp)
                            cam.CFrame = cam.CFrame:Lerp(wanted, 0.15)
                        end
                    end)
                    if VD.TOFV1_Laser then ToF1_UpdateLaser(op, tp)
                    elseif ToF1State.LaserBeam then ToF1State.LaserBeam.Transparency = 1 end
                elseif ToF1State.LaserBeam then ToF1State.LaserBeam.Transparency = 1 end
            end)
        end
        local function ToF1_StopConn()
            if ToF1State.Connection then pcall(function() ToF1State.Connection:Disconnect() end); ToF1State.Connection = nil end
            ToF1State.IsAiming = false
            ToF1State.TouchInput = nil
            ToF1_ClearLaser()
        end
        local SetToFSilentAimV1
        local function ToF1_EnsureInputs()
            if not ToF1State.InputBegan then
                ToF1State.InputBegan = UserInputService.InputBegan:Connect(function(inp, gp)
                    if gp then return end
                    local k = ToF1KeyCodes[VD.TOFV1_Key or "None"]
                    if k and inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == k then SetToFSilentAimV1(not VD.TOFV1_SilentAim); return end
                    if not VD.TOFV1_SilentAim then return end
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or (inp.UserInputType == Enum.UserInputType.Touch and ToF1_IsTouchShoot(inp)) then
                        if ToF1_IsBlocked() then ToF1State.IsAiming = false; return end
                        ToF1State.IsAiming = true
                        if inp.UserInputType == Enum.UserInputType.Touch then ToF1State.TouchInput = inp end
                        return
                    end
                    if inp.UserInputType == Enum.UserInputType.Keyboard then
                        if inp.KeyCode == Enum.KeyCode.K then ToF1_SetTargetMode("Killer", true)
                        elseif inp.KeyCode == Enum.KeyCode.J then ToF1_SetTargetMode("Survivors", true)
                        elseif inp.KeyCode == Enum.KeyCode.L then ToF1_SetTargetMode("Zombie", true) end
                    end
                end)
            end
            if not ToF1State.InputEnded then
                ToF1State.InputEnded = UserInputService.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or (inp.UserInputType == Enum.UserInputType.Touch and inp == ToF1State.TouchInput) then
                        local wa = ToF1State.IsAiming
                        ToF1State.IsAiming = false
                        if inp == ToF1State.TouchInput then ToF1State.TouchInput = nil end
                        if ToF1State.LaserBeam then ToF1State.LaserBeam.Transparency = 1 end
                        if wa then if ToF1_IsBlocked() then return end; ToF1_Shoot() end
                    end
                end)
            end
        end
        SetToFSilentAimV1 = function(en)
            if en and W.SetPistolV2Enabled and VD.SilentPistolV2Enabled then W.SetPistolV2Enabled(false) end
            VD.TOFV1_SilentAim = en and true or false
            ToF1_EnsureInputs()
            if VD.TOFV1_SilentAim then ToF1_CreateUI(); ToF1_StartConn()
            else ToF1_DestroyUI(); ToF1_StopConn() end
        end
        W.SetToFSilentAimV1 = SetToFSilentAimV1
        W.ToF1_ClearLaser = ToF1_ClearLaser
        W.ToF1_SetTargetMode = ToF1_SetTargetMode
        ToF1_EnsureInputs()
        if VD.TOFV1_SilentAim then
            task.defer(function() pcall(function() SetToFSilentAimV1(true) end) end)
        end


        -- =====================================================================
        -- Keep V2 internals in a separate lexical scope to stay under Luau's 200-local limit.
        do
        -- Silent Pistol V2 reuses the reference Silent Pistol V1 targeting and ToF.Fire payload.
        -- Source behavior: weapon-origin direction, quadratic projectile intercept,
        -- nearest Killer / camera-forward Survivor or SCP target, RMB aim + LMB fire.
        -- State and connections are intentionally independent from the V1 engine.
        local PistolV2State = {
            Enabled = false, Aiming = false, Connection = nil, Laser = nil,
            InputBegan = nil, InputEnded = nil,
            MobileGui = nil, MobileBegan = nil, MobileEnded = nil,
            TargetGui = nil, TargetDragConnections = {}, TargetModeButtons = {},
            SavedUIPos = UDim2.new(0.5, -100, 0, 280),
            VelocityCache = {}, SCPs = {}, SCPCacheAt = 0
        }
        local function PistolV2_IsDowned(character)
            if not character then return true end
            local root = character:FindFirstChild("HumanoidRootPart")
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            return not root or (humanoid and humanoid.Health <= 0)
                or character:GetAttribute("Knocked") == true
                or character:GetAttribute("isKnocked") == true
                or character:GetAttribute("IsHooked") == true
                or character:GetAttribute("isHooked") == true
        end
        local function PistolV2_IsBlocked()
            if VD.TOFV2_BlockKnocked == false then return false end
            return PistolV2_IsDowned(LocalPlayer.Character)
        end
        local function PistolV2_GetEvent()
            local remotes = ReplicatedStorage:FindFirstChild("Remotes")
            local items = remotes and remotes:FindFirstChild("Items")
            local tof = items and items:FindFirstChild("Twist of Fate")
            local fire = tof and tof:FindFirstChild("Fire")
            return fire and fire:IsA("RemoteEvent") and fire or nil
        end
        local function PistolV2_GetGun()
            -- Match the reference hierarchy and preference: gun first, then EmperorGun.
            local character = LocalPlayer.Character
            if not character then return nil end
            local tof = character:FindFirstChild("Twist of Fate", true)
            if not tof then return nil end
            local arm = tof:FindFirstChild("Right Arm")
            if arm then
                local gun = arm:FindFirstChild("gun")
                if gun then return gun end
                local emperorGun = arm:FindFirstChild("EmperorGun")
                if emperorGun then return emperorGun end
            end
            return tof
        end
        local function PistolV2_GetOrigin(gun, character, root)
            -- Use the weapon's actual origin as in the reference Silent Pistol V1.
            if not (character and root and gun) then return nil end
            if character:GetAttribute("IsCarried") then
                return root.Position + root.CFrame.LookVector * 2
            end
            local origin
            pcall(function()
                if gun:IsA("BasePart") then
                    origin = gun.Position
                else
                    local part = gun:FindFirstChildOfClass("BasePart")
                    if part then origin = part.Position end
                end
            end)
            return origin or Vector3.new(root.Position.X, root.Position.Y + 1.5, root.Position.Z)
        end
        local function PistolV2_IsVisible(origin, targetPosition, targetCharacter)
            local delta = targetPosition - origin
            local distance = delta.Magnitude
            if distance < 0.1 then return true end
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local excluded = {}
            local ownCharacter = LocalPlayer.Character
            if ownCharacter then table.insert(excluded, ownCharacter) end
            if targetCharacter and targetCharacter ~= ownCharacter then table.insert(excluded, targetCharacter) end
            if PistolV2State.Laser then table.insert(excluded, PistolV2State.Laser) end
            params.FilterDescendantsInstances = excluded
            return workspace:Raycast(origin, delta.Unit * distance, params) == nil
        end
        local function PistolV2_GetVelocity(character, targetPart)
            -- Smoothed HumanoidRootPart velocity, matching the reference implementation.
            local root = character and (character:FindFirstChild("HumanoidRootPart") or targetPart)
            if not root or not root:IsA("BasePart") then return Vector3.zero end
            local position, now = root.Position, tick()
            local previous = PistolV2State.VelocityCache[character]
            if previous then
                local dt = now - previous.time
                if dt > 0.001 and dt < 0.1 then
                    local measured = (position - previous.position) / dt
                    local velocity = previous.velocity:Lerp(measured, 0.4)
                    PistolV2State.VelocityCache[character] = { position = position, velocity = velocity, time = now }
                    return velocity
                end
            end
            local velocity = root.Velocity
            PistolV2State.VelocityCache[character] = { position = position, velocity = velocity, time = now }
            return velocity
        end
        local function PistolV2_Intercept(origin, targetPart, targetCharacter)
            -- Quadratic projectile intercept from the reference V1; prediction is skipped at close range.
            local position = targetPart.Position
            local offset = position - origin
            if offset.Magnitude < 8 then return position end

            local velocity = PistolV2_GetVelocity(targetCharacter, targetPart)
            local speed = math.max(tonumber(VD.TOFV2_ProjectileSpeed) or 500, 1)
            local a = velocity:Dot(velocity) - speed * speed
            local b = 2 * offset:Dot(velocity)
            local c = offset:Dot(offset)
            local flightTime

            if math.abs(a) < 0.01 then
                if math.abs(b) > 0.01 then
                    local candidate = -c / b
                    if candidate > 0.001 then flightTime = candidate end
                end
            else
                local discriminant = b * b - 4 * a * c
                if discriminant >= 0 then
                    local root = math.sqrt(discriminant)
                    local t1 = (-b - root) / (2 * a)
                    local t2 = (-b + root) / (2 * a)
                    if t1 > 0.001 then
                        flightTime = t1
                    elseif t2 > 0.001 then
                        flightTime = t2
                    end
                end
            end

            if flightTime then
                local efficiency = math.clamp(tonumber(VD.TOFV2_PredictionEfficiency) or 0.85, 0.1, 1)
                return position + velocity * efficiency * flightTime
            end
            return position
        end
        local function PistolV2_GetSCPs()
            -- Match the reference cache: SCP/corpse models identified by their attributes.
            if tick() - PistolV2State.SCPCacheAt < 0.5 then return PistolV2State.SCPs end
            local output = {}
            local map = workspace:FindFirstChild("Map")
            if map then
                for _, model in ipairs(map:GetDescendants()) do
                    if model:IsA("Model") then
                        local attributes = model:GetAttributes()
                        if model:GetAttribute("CorpseCreated0492") or next(attributes) ~= nil then
                            local root = model:FindFirstChild("HumanoidRootPart")
                            if root and root:IsA("BasePart") then table.insert(output, root) end
                        end
                    end
                end
            end
            PistolV2State.SCPs, PistolV2State.SCPCacheAt = output, tick()
            return output
        end
        local function PistolV2_GetTarget()
            -- Reference V1 target selection and ToF.Fire payload semantics.
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local gun = PistolV2_GetGun()
            if not (character and root and gun) then return nil, nil, nil, nil end

            local origin = PistolV2_GetOrigin(gun, character, root)
            if not origin then return nil, nil, nil, nil end
            local mode = VD.TOFV2_TargetMode or "Killer"
            local targetPart, targetCharacter
            local camera = workspace.CurrentCamera

            local function getBodyPart(model)
                if not model then return nil end
                -- The source prefers Torso; fallbacks keep this compatible with alternate rigs.
                return model:FindFirstChild("Torso")
                    or model:FindFirstChild("UpperTorso")
                    or model:FindFirstChild("HumanoidRootPart")
            end

            if mode == "Killer" then
                local nearest = math.huge
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer and player.Team and player.Team.Name == "Killer" and player.Character then
                        local part = getBodyPart(player.Character)
                        if part and part:IsA("BasePart") then
                            local distance = (part.Position - root.Position).Magnitude
                            if distance < nearest then
                                nearest, targetPart, targetCharacter = distance, part, player.Character
                            end
                        end
                    end
                end
            elseif mode == "Survivors" then
                if not camera then return nil, nil, nil, nil end
                local look = camera.CFrame.LookVector
                local bestDot = -math.huge
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer and player.Team and player.Team.Name == "Survivors" and player.Character then
                        local part = getBodyPart(player.Character)
                        if part and part:IsA("BasePart") then
                            local delta = part.Position - camera.CFrame.Position
                            if delta.Magnitude > 0.001 then
                                local dot = look:Dot(delta.Unit)
                                if dot > 0.5 and dot > bestDot then
                                    bestDot, targetPart, targetCharacter = dot, part, player.Character
                                end
                            end
                        end
                    end
                end
            elseif mode == "Zombie" then
                if not camera then return nil, nil, nil, nil end
                local look = camera.CFrame.LookVector
                local bestDot = -math.huge
                for _, rootPart in ipairs(PistolV2_GetSCPs()) do
                    local model = rootPart and rootPart.Parent
                    if rootPart and rootPart.Parent then
                        local delta = rootPart.Position - camera.CFrame.Position
                        if delta.Magnitude > 0.001 then
                            local dot = look:Dot(delta.Unit)
                            if dot > 0.5 and dot > bestDot then
                                bestDot, targetPart, targetCharacter = dot, rootPart, model
                            end
                        end
                    end
                end
            end

            if not (targetPart and targetCharacter) then return nil, nil, nil, nil end
            if VD.TOFV2_WallCheck and not PistolV2_IsVisible(origin, targetPart.Position, targetCharacter) then
                return nil, nil, nil, nil
            end

            local targetPosition = targetPart.Position
            if VD.TOFV2_Predict then
                targetPosition = PistolV2_Intercept(origin, targetPart, targetCharacter)
            end
            local direction = targetPosition - origin
            if direction.Magnitude < 0.1 then return nil, nil, nil, nil end
            return direction.Unit, gun, origin, targetPosition
        end
        local function PistolV2_ClearLaser()
            if PistolV2State.Laser then pcall(function() PistolV2State.Laser:Destroy() end); PistolV2State.Laser = nil end
            pcall(function()
                for _, item in ipairs(workspace:GetChildren()) do
                    if item:IsA("BasePart") and item.Name == "PistolV2Laser" then item:Destroy() end
                end
            end)
        end
