                    button.BackgroundColor3 = active and Color3.fromRGB(37, 44, 55) or Color3.fromRGB(24, 24, 30)
                    button.TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(145, 145, 158)
                    local stroke = button:FindFirstChildOfClass("UIStroke")
                    if stroke then
                        stroke.Color = active and Color3.fromRGB(255, 170, 64) or Color3.fromRGB(52, 52, 65)
