                local delta = input.Position - dragStart
                local camera = workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(360, 720)
                local x = math.clamp(startPos.X + delta.X, 0, math.max(0, viewport.X - frame.AbsoluteSize.X))
