            VD.StretchResEnabled = VD.StretchResEnabled == true
            VD.StretchResAmount = math.clamp(tonumber(VD.StretchResAmount) or 0.67, 0.4, 1)
            local STRETCH_RES_BIND_NAME = "MAWWW_HUB_STRETCH_RESOLUTION"
            local function StopStretchResolution()
                pcall(function()
                    RunService:UnbindFromRenderStep(STRETCH_RES_BIND_NAME)
                end)
            end
            local function StartStretchResolution()
                -- Rebind by a stable name so script re-execution cannot create duplicate loops.
                StopStretchResolution()
                local ok, err = pcall(function()
                    RunService:BindToRenderStep(STRETCH_RES_BIND_NAME, Enum.RenderPriority.Camera.Value + 1, function()
                        if not VD.StretchResEnabled then return end
                        local camera = workspace.CurrentCamera
                        if not camera then return end
                        local amount = math.clamp(tonumber(VD.StretchResAmount) or 0.67, 0.4, 1)
                        camera.CFrame = camera.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, amount, 0, 0, 0, 1)
                    end)
                end)
                if not ok then
                    warn("[MAWWW] Stretch Resolution failed to start: " .. tostring(err))
                end
            end
            local function SetStretchResolution(enabled)
                VD.StretchResEnabled = enabled == true
                if VD.StretchResEnabled then
                    StartStretchResolution()
                else
                    StopStretchResolution()
                end
            end

