            -- Anti Hook: periodically sends the game's character-look update while carried.
            local antiHookAccumulator = 0
            local function FindAntiHookRemote()
                local remotes = ReplicatedStorage:FindFirstChild("Remotes")
                local gameRemotes = remotes and remotes:FindFirstChild("Game")
                local remote = gameRemotes and gameRemotes:FindFirstChild("UpdateCharacterLook")
                if remote and remote:IsA("RemoteEvent") then return remote end
                return nil
            end
            RunService.Heartbeat:Connect(function(deltaTime)
                if not VD.AntiHookEnabled then antiHookAccumulator = 0; return end
                local character = LocalPlayer.Character
                if not character or character:GetAttribute("IsCarried") ~= true then
                    antiHookAccumulator = 0
                    return
                end
                local hz = math.clamp(tonumber(VD.AntiHookHz) or 44, 1, 60)
                local interval = 1 / hz
                antiHookAccumulator = math.min(antiHookAccumulator + deltaTime, interval * 3)
                local sends = 0
                while antiHookAccumulator >= interval and sends < 3 do
                    antiHookAccumulator = antiHookAccumulator - interval
                    sends = sends + 1
                    local remote = FindAntiHookRemote()
                    if remote then
                        local normal = CFrame.new(0, 1, 0)
                        local offset = CFrame.new(0, -(tonumber(VD.AntiHookOffset) or 250), 0)
                        pcall(function() remote:FireServer(normal, offset, offset, offset, offset) end)
                    end
                end
            end)
            local antiHookSection = MakeSection(SurvivorTab, "Anti Hook")
            antiHookSection:AddToggle({
                Title = "Anti Hook",
                Content = "Mencoba membatalkan state carried melalui update character-look.",
                Default = VD.AntiHookEnabled,
                ConfigId = "AntiHookEnabled",
                Callback = function(enabled)
                    VD.AntiHookEnabled = enabled == true
                    antiHookAccumulator = 0
                    VD_Notify("Anti Hook", VD.AntiHookEnabled and "Enabled" or "Disabled", 2)
                end
            })
            antiHookSection:AddSlider({
                Title = "Offset",
                Min = 50, Max = 1000, Default = VD.AntiHookOffset, Increment = 50,
                ConfigId = "AntiHookOffset",
                Callback = function(value) VD.AntiHookOffset = tonumber(value) or 250 end
            })
            antiHookSection:AddSlider({
                Title = "Send Rate",
                Min = 1, Max = 60, Default = VD.AntiHookHz, Increment = 1,
                ConfigId = "AntiHookHz",
                Callback = function(value) VD.AntiHookHz = math.clamp(tonumber(value) or 44, 1, 60) end
            })

