        if not draggingFloating or not dragStart or not floatingStart then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        local delta = input.Position - dragStart
        floating.Position = UDim2.new(
            floatingStart.X.Scale, floatingStart.X.Offset + delta.X,
            floatingStart.Y.Scale, floatingStart.Y.Offset + delta.Y
        )
    end))

    local function musicFormatTime(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end

    local function musicUpdateFloating()
        local song = MUSIC_SONGS[musicCurrent]
        if not song then return end
        floatingTitle.Text = song.name
        floatingArtist.Text = song.artist ~= "" and song.artist or ("MAWWW HUB • Track " .. tostring(musicCurrent))
        if musicSound.IsPlaying then
            floatingPlay.Text = "Ⅱ"
