                    or COLORS.Panel2
            end
        end
    end

    local function musicSetFloatingVisible(enabled)
        musicFloatingVisible = enabled == true
        floating.Visible = musicFloatingVisible
        showFloating.Text = musicFloatingVisible and "FLOAT ON" or "FLOAT OFF"
        showFloating.TextColor3 = musicFloatingVisible and COLORS.Cyan or COLORS.Muted
        showFloating.BackgroundColor3 = musicFloatingVisible and Color3.fromRGB(24, 91, 130) or COLORS.Panel3
    end

    local function musicNextIndex()
        if musicShuffle then
            if #MUSIC_SONGS <= 1 then return musicCurrent end
            local nextIndex = musicCurrent
            for _ = 1, 8 do
                nextIndex = math.random(1, #MUSIC_SONGS)
                if nextIndex ~= musicCurrent then break end
            end
            return nextIndex
        end
        return (musicCurrent % #MUSIC_SONGS) + 1
    end

    local function musicLoadSong(index, autoplay)
        if not MUSIC_SONGS[index] then return end
        musicLoadToken += 1
        local myToken = musicLoadToken
        musicCurrent = index
        local song = MUSIC_SONGS[index]

        musicSound:Stop()
        musicSound.SoundId = ""
        musicSound.TimePosition = 0
        musicLoading = true
        musicUpdateFloating()
        musicHighlight()

        task.spawn(function()
            local okSet = pcall(function()
                musicSound.SoundId = song.id
            end)
            if not okSet or myToken ~= musicLoadToken then
                musicLoading = false
                return
            end

            local loaded = false
            local failed = false
            local loadedConnection = musicSound.Loaded:Connect(function()
                loaded = true
            end)

            local okPreload = pcall(function()
                MusicContentProvider:PreloadAsync({musicSound})
            end)
            if not okPreload then
                failed = true
            end

            local deadline = os.clock() + 8
            while not loaded and not failed and os.clock() < deadline do
                if myToken ~= musicLoadToken then
                    loadedConnection:Disconnect()
                    return
                end
                if musicSound.TimeLength > 0 then
                    loaded = true
                    break
                end
                task.wait(0.1)
            end
            loadedConnection:Disconnect()

            if myToken ~= musicLoadToken then return end

            musicLoading = false
            if not loaded or musicSound.TimeLength <= 0 then
                floatingTitle.Text = "Audio gagal dimuat"
                floatingArtist.Text = song.name
                floatingPlay.Text = "▶"
                task.wait(0.25)
                if myToken == musicLoadToken then
                    local nextIndex = musicNextIndex()
                    if nextIndex ~= index then
                        musicLoadSong(nextIndex, true)
                    end
                end
                return
            end

            musicUpdateFloating()
            if autoplay then
                pcall(function() musicSound:Play() end)
            end
            musicUpdateFloating()
        end)
    end

