            ]]
            local ok, imageUri = pcall(function()
                local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                local lookup = {}
                for i = 1, #alphabet do
                    lookup[string.sub(alphabet, i, i)] = i - 1
                end

                local output = {}
                local buffer, bitCount = 0, 0
                for i = 1, #encodedLogo do
                    local char = string.sub(encodedLogo, i, i)
                    if char == "=" then break end
                    local value = lookup[char]
                    if value ~= nil then
                        buffer = buffer * 64 + value
                        bitCount = bitCount + 6
                        if bitCount >= 8 then
                            bitCount = bitCount - 8
                            output[#output + 1] = string.char(math.floor(buffer / (2 ^ bitCount)) % 256)
                            buffer = buffer % (2 ^ bitCount)
                        end
                    end
                end

                local imageFile = "mawww_hub_mawww_catgirl_floating_icon.png"
                writefile(imageFile, table.concat(output))
                return assetGetter(imageFile)
            end)
