--==============================================================
-- JUNKIE KEY PROVIDER LOGIC
-- Keeps the original key UI above; only provider validation is replaced.
--==============================================================

local KEY_FILE = SAVE_FILE
local Junkie = nil
local junkieLoadError = nil

local function resolveKeyEnv()
    if type(getgenv) == "function" then
        local ok, value = pcall(getgenv)
        if ok and type(value) == "table" then
            return value
        end
    end
    return _G
end

local function SaveKey(key)
    pcall(function()
        if type(writefile) == "function" then
            writefile(KEY_FILE, key)
        end
    end)
    pcall(function()
        local env = resolveKeyEnv()
        env.SCRIPT_KEY = key
        env.script_key = key
    end)
end

local function LoadKey()
    local saved
    pcall(function()
        if type(isfile) == "function"
            and type(readfile) == "function"
            and isfile(KEY_FILE) then
            saved = readfile(KEY_FILE)
            if saved then
                saved = tostring(saved):gsub("^%s+", ""):gsub("%s+$", "")
                if saved == "" then saved = nil end
            end
        end
    end)
    return saved
end

local function ClearKey()
    pcall(function()
        if type(delfile) == "function"
            and type(isfile) == "function"
            and isfile(KEY_FILE) then
            delfile(KEY_FILE)
        end
    end)
end

local function setPromersStatus(message, good)
    KeyStatus.Text = tostring(message or "")
    KeyStatus.TextColor3 = good and COLORS.Green or Color3.fromRGB(255, 185, 195)
end

local function loadJunkieProvider()
    if Junkie then
        return Junkie
    end
    if junkieLoadError then
        return nil, junkieLoadError
    end

    local ok, result = pcall(function()
        local source = game:HttpGet(JUNKIE_LIBRARY_URL)
        if type(source) ~= "string" or #source < 100 then
            error("Junkie SDK download returned an empty response")
        end
        local lowered = source:gsub("^%s+", ""):lower()
        if lowered:match("^<!doctype html") or lowered:match("^<html") then
            error("Junkie SDK URL returned HTML instead of Lua source")
        end
        local compiler = loadstring or load
        if type(compiler) ~= "function" then
            error("Executor does not support loadstring/load")
        end
        local chunk, compileError = compiler(source, "@JunkieKeyProvider")
        if type(chunk) ~= "function" then
            error(tostring(compileError or "Junkie SDK did not compile"))
        end
        local sdk = chunk()
        if type(sdk) ~= "table" or type(sdk.check_key) ~= "function" then
            error("Junkie SDK is missing check_key()")
        end
        sdk.service = JUNKIE_SERVICE
        sdk.identifier = JUNKIE_IDENTIFIER
        sdk.provider = JUNKIE_PROVIDER
        return sdk
    end)

    if not ok then
        junkieLoadError = tostring(result)
        return nil, junkieLoadError
    end
    Junkie = result
    return Junkie
end

local verifying = false
local authorized = false

local function requestKeyLink()
    local provider, providerError = loadJunkieProvider()
    if not provider then
        setPromersStatus("Key provider unavailable.", false)
        warn("[MAWWW] Junkie SDK: " .. tostring(providerError))
        return
    end
    if type(provider.get_key_link) ~= "function" then
        setPromersStatus("Key link is unavailable from provider.", false)
        return
    end

    setPromersStatus("Requesting key link...", true)
    task.spawn(function()
        local callOK, link, linkError = pcall(provider.get_key_link)
        if not callOK then
            setPromersStatus("Could not request key link.", false)
            warn("[MAWWW] Junkie get_key_link: " .. tostring(link))
            return
        end
        if type(link) ~= "string" or not link:match("^https?://") then
            setPromersStatus("Key link unavailable; try again later.", false)
            warn("[MAWWW] Junkie get_key_link: " .. tostring(linkError or link or "no link returned"))
            return
        end

        local copied = false
        if type(setclipboard) == "function" then
            copied = pcall(setclipboard, link)
        elseif type(toclipboard) == "function" then
            copied = pcall(toclipboard, link)
        end
        if copied then
            setPromersStatus("Key link copied to clipboard.", true)
            print("[MAWWW] Junkie key link: " .. link)
        else
            setPromersStatus("Key link printed to console.", true)
            warn("[MAWWW] Copy this Junkie key link: " .. link)
        end
    end)
end

local function verifyKey(key, fromSaved)
    if verifying or authorized then return end

    key = tostring(key or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if key == "" then
        requestKeyLink()
        return
    end

    verifying = true
    KeyInput.Text = key
    setPromersStatus(fromSaved and "Checking saved key..." or "Checking license key...", true)

    task.spawn(function()
        local provider, providerError = loadJunkieProvider()
        if not provider then
            setPromersStatus("Key provider unavailable.", false)
            warn("[MAWWW] Junkie SDK: " .. tostring(providerError))
            verifying = false
            return
        end

        local checkOK, validation, validationExtra = pcall(provider.check_key, key)
        if not checkOK then
            setPromersStatus("Key verification request failed.", false)
            warn("[MAWWW] Junkie check_key: " .. tostring(validation))
            verifying = false
            return
        end

        local valid = type(validation) == "table"
            and (validation.valid == true or validation.success == true)
        if not valid then
            local reason = "KEY_INVALID"
            if type(validation) == "table" then
                reason = tostring(validation.error or validation.message or reason)
            elseif validation ~= nil then
                reason = tostring(validation)
            elseif validationExtra ~= nil then
                reason = tostring(validationExtra)
            end
            setPromersStatus("Key rejected: " .. reason, false)
            if fromSaved then ClearKey() end
            verifying = false
            return
        end

        SaveKey(key)
        authorized = true
        setPromersStatus("Key accepted ✓ License verified", true)
        task.wait(1.5)

        -- Keep the existing MAWWW key UI behavior and start the original hub.
        pcall(function()
            if KeyGui and KeyGui.Parent then
                KeyGui:Destroy()
            end
        end)

        print("[MAWWW] Junkie key verified ✓ launching HUB")
        task.defer(function()
            local mainOK, mainErr = pcall(function()
                createFeatureUI("VILONCE DISTRICT")
            end)
            if not mainOK then
                warn("[MAWWW] Main UI startup error:", mainErr)
            end
        end)
        verifying = false
    end)
end

VerifyButton.MouseEnter:Connect(function()
    if verifying then return end
    tween(VerifyButton, 0.12, {
