        BackgroundColor3 = Color3.fromRGB(41, 96, 165),
    }):Play()
end)

VerifyButton.Activated:Connect(function()
    verifyKey(KeyInput.Text, false)
end)

KeyInput.FocusLost:Connect(function(enterPressed)
    if enterPressed then
        verifyKey(KeyInput.Text, false)
    end
end)

KeyClose.Activated:Connect(function()
    if KeyGui and KeyGui.Parent then
        KeyGui:Destroy()
    end
end)

-- Automatically try the saved key, if the executor supports file APIs.
task.spawn(function()
    task.wait(0.6)
    local saved = LoadKey()
    if saved then
        KeyInput.Text = saved
        setPromersStatus("Saved key detected • Auto verifying...", true)
        task.wait(0.4)
        verifyKey(saved, true)
    end
end)

